const BASE_COURSE={"meta":{"title":"General Chemistry Foundations","subtitle":"A two-semester, majors-level foundation for the rest of chemistry.","scope":"ChemWaypoint instructional sequence aligned to the University of Arkansas chemistry/biochemistry degree spine, UArk CHEM 12073/12071 context, ACS introductory-chemistry expectations, and the common two-semester general-chemistry scope reflected by OpenStax Chemistry 2e. This is not an official University of Arkansas syllabus.","sources":[{"label":"University of Arkansas Chemistry & Biochemistry catalog","url":"https://catalog.uark.edu/undergraduatecatalog/collegesandschools/jwilliamfulbrightcollegeofartsandsciences/chemistryandbiochemistrychbc/"},{"label":"ACS undergraduate coursework guidance","url":"https://www.acs.org/education/policies/acs-approval-program/guidelines/coursework.html"},{"label":"OpenStax Chemistry 2e","url":"https://openstax.org/details/books/chemistry-2e"}]},"semesters":[{"number":1,"title":"General Chemistry I","code":"CHEM 12073 / 14103 pathway","focus":"Measurement → particles → reactions → energy → electrons → structure → gases"},{"number":2,"title":"General Chemistry II","code":"CHEM 12283 / 14203 pathway","focus":"Forces → solutions → rates → equilibrium → acids/bases → thermodynamics → electrochemistry"}],"modules":[{"id":"measurement","semester":1,"number":1,"title":"Measurement, Units & Chemical Reasoning","subtitle":"How chemists turn observations into defensible numbers.","prerequisite":"None","outcomes":["Distinguish qualitative observations from quantitative measurements","Use SI units, metric prefixes and derived units","Apply significant-figure rules without losing precision","Use dimensional analysis to convert between units and connect quantities"],"sections":[{"title":"Measurements are models of reality","body":["A measurement is never just a number. It contains a magnitude, a unit, and an implied level of certainty. Writing 12.0 mL communicates more information than writing 12 mL because the trailing zero indicates the measurement was resolved to the tenths place.","Chemistry depends on comparing quantities across scales: picometers for bond lengths, grams for samples, liters for gases, and moles for particle counts. Units keep those quantities meaningful and allow equations to act as built-in error checks."]},{"title":"Precision, accuracy and significant figures","body":["Accuracy asks how close a result is to an accepted or true value; precision asks how reproducible repeated measurements are. A set of measurements can be precise but systematically wrong, or accurate on average but imprecise.","For multiplication and division, the result is limited by the factor with the fewest significant figures. For addition and subtraction, the result is limited by the least precise decimal place. Keep extra digits during intermediate steps and round once at the end."]},{"title":"Dimensional analysis is chemistry’s universal translator","body":["A conversion factor is a ratio equal to one. Arrange conversion factors so unwanted units cancel algebraically. The same logic later drives stoichiometry: grams → moles → mole ratio → moles → grams is simply dimensional analysis using chemical relationships."]}],"equations":[{"label":"Density","expression":"ρ = m / V"},{"label":"Percent error","expression":"% error = |experimental − accepted| / accepted × 100%"}],"example":{"prompt":"A liquid sample has a mass of 18.42 g and a volume of 15.0 mL. Find its density with appropriate significant figures.","steps":["Use ρ = m/V.","18.42 g ÷ 15.0 mL = 1.228 g/mL.","The volume has 3 significant figures, so report 3 significant figures."],"answer":"1.23 g/mL"},"check":{"question":"Which result correctly reports 12.51 g ÷ 3.2 mL?","choices":["3.909 g/mL","3.91 g/mL","3.9 g/mL","4 g/mL"],"answer":2,"explanation":"Division is limited by the factor with the fewest significant figures. 3.2 has two significant figures, so the result is 3.9 g/mL."},"bridge":{"course":"Every later chemistry course","text":"Unit analysis is the error-checking language behind stoichiometry, kinetics, thermodynamics, spectroscopy, enzyme assays and analytical calibration."},"lab":"Connects directly to density, mass/volume measurement, uncertainty, graphing and laboratory notebook practice.","tool":null,"vocabulary":["SI unit","derived unit","precision","accuracy","significant figures","dimensional analysis","density"]},{"id":"atoms-moles","semester":1,"number":2,"title":"Atoms, Isotopes & the Mole","subtitle":"Connecting submicroscopic particles to laboratory-scale matter.","prerequisite":"Measurement & Units","outcomes":["Describe atoms using protons, neutrons and electrons","Relate atomic number and mass number to isotope notation","Calculate weighted-average atomic mass","Use Avogadro’s constant to move between particles and moles"],"sections":[{"title":"Atomic identity comes from proton count","body":["The atomic number Z is the number of protons in the nucleus and defines the element. Neutral atoms have equal numbers of protons and electrons; ions form when electrons are gained or lost.","Isotopes are atoms of the same element with different numbers of neutrons. They therefore share chemical identity but differ in mass. A nuclide is commonly written with mass number A as a superscript and atomic number Z as a subscript."]},{"title":"Average atomic mass is a weighted average","body":["The decimal atomic masses on the periodic table are not usually the mass of one particular atom. They represent the abundance-weighted average of naturally occurring isotopes. A rare heavy isotope contributes less to the average than a common light isotope."]},{"title":"The mole bridges particles and grams","body":["Atoms and molecules are too small to count individually in the laboratory, so chemists count them by grouping 6.02214076 × 10²³ entities into one mole. Molar mass converts between the amount of substance in moles and measurable mass in grams.","This bridge is foundational: nearly every quantitative reaction problem begins by converting a measured quantity into moles."]}],"equations":[{"label":"Avogadro constant","expression":"Nₐ = 6.02214076 × 10²³ mol⁻¹"},{"label":"Moles from mass","expression":"n = m / M"},{"label":"Weighted atomic mass","expression":"average mass = Σ(fractional abundance × isotope mass)"}],"example":{"prompt":"How many carbon atoms are present in 0.250 mol C?","steps":["Start from amount in moles.","Multiply by Avogadro’s constant: 0.250 mol × 6.022 × 10²³ atoms/mol.","Cancel mol and round to three significant figures."],"answer":"1.51 × 10²³ carbon atoms"},"check":{"question":"An ion has 17 protons and 18 electrons. What is its charge?","choices":["+1","0","−1","−17"],"answer":2,"explanation":"One more electron than protons gives a net charge of −1. An atom with 17 protons is chlorine, so the ion is Cl⁻."},"bridge":{"course":"Analytical chemistry & biochemistry","text":"Moles make concentration, titration, reaction yield, enzyme assays and biomolecular preparation quantitatively possible."},"lab":"Supports mass-based composition experiments and the interpretation of hydrates and reaction stoichiometry.","tool":null,"vocabulary":["atomic number","mass number","isotope","ion","mole","Avogadro constant","molar mass"]},{"id":"formulas","semester":1,"number":3,"title":"Formulas, Nomenclature & Composition","subtitle":"Learning to read and write the symbolic language of substances.","prerequisite":"Atoms, Isotopes & the Mole","outcomes":["Differentiate molecular, empirical and structural formulas","Name common ionic and molecular compounds","Calculate formula mass and percent composition","Determine empirical and molecular formulas from composition data"],"sections":[{"title":"A chemical formula encodes composition","body":["An empirical formula gives the simplest whole-number atom ratio. A molecular formula gives the actual number of each atom in a molecule. Structural formulas add connectivity, which becomes crucial in organic chemistry because different structures can share the same molecular formula.","For ionic compounds, the formula represents the lowest whole-number ratio of ions needed for electrical neutrality rather than a discrete molecule."]},{"title":"Nomenclature communicates charge and composition","body":["For ionic compounds, name the cation first and the anion second. Transition-metal charges are often specified with Roman numerals because one metal can form several common cations. Molecular compounds between nonmetals use prefixes to communicate atom counts.","Learning names is not only memorization: naming forces you to reason about charges, common ions and chemical families."]},{"title":"Composition connects formulas to measurements","body":["Percent composition tells what fraction of a compound’s mass comes from each element. Combustion analysis and other composition measurements can be converted to moles of elements, simplified to whole-number ratios and used to infer an empirical formula."]}],"equations":[{"label":"Mass percent","expression":"mass % element = mass element / mass compound × 100%"},{"label":"Molecular formula","expression":"molecular formula = (empirical formula)ₙ"}],"example":{"prompt":"A compound contains 40.0% C, 6.7% H and 53.3% O by mass. Find the empirical formula.","steps":["Assume 100 g: 40.0 g C, 6.7 g H, 53.3 g O.","Convert each to moles: about 3.33 mol C, 6.65 mol H, 3.33 mol O.","Divide by the smallest: C : H : O ≈ 1 : 2 : 1."],"answer":"CH₂O"},"check":{"question":"What is the correct formula for aluminum oxide?","choices":["AlO","Al₂O","AlO₂","Al₂O₃"],"answer":3,"explanation":"Al forms Al³⁺ and oxide is O²⁻. The lowest neutral combination is 2 Al³⁺ and 3 O²⁻, giving Al₂O₃."},"bridge":{"course":"Organic chemistry","text":"Organic chemistry expands “formula” into connectivity and functional groups; the distinction between molecular and structural formula becomes central to isomerism."},"lab":"Connects to composition, waters of hydration, separations and identification of unknowns.","tool":null,"vocabulary":["empirical formula","molecular formula","formula unit","percent composition","polyatomic ion","nomenclature"]},{"id":"stoichiometry","semester":1,"number":4,"title":"Chemical Reactions & Stoichiometry","subtitle":"Using balanced equations as quantitative maps.","prerequisite":"Formulas, Nomenclature & Composition","outcomes":["Balance chemical equations by conserving atoms","Interpret coefficients as mole ratios","Solve mass–mass and solution stoichiometry problems","Identify limiting reactants and calculate theoretical and percent yield"],"sections":[{"title":"Balanced equations express conservation of matter","body":["Chemical reactions rearrange atoms; they do not create or destroy them. Coefficients are adjusted until each element has the same atom count on both sides. Never change subscripts to balance an equation because that changes the identity of the substances.","The coefficients are simultaneously particle ratios and mole ratios. For 2 H₂ + O₂ → 2 H₂O, two molecules or two moles of H₂ react with one of O₂ to form two of H₂O."]},{"title":"The mole ratio is the reaction’s conversion factor","body":["Most stoichiometry problems follow the same architecture: convert the given quantity to moles, use the balanced-equation coefficient ratio, then convert to the desired unit. This is dimensional analysis with chemical meaning."]},{"title":"The limiting reactant controls how far the reaction can proceed","body":["When reactants are not present in exact stoichiometric proportions, one is consumed first. That limiting reactant sets the maximum possible product, called theoretical yield. Actual yield is usually lower because reactions can be incomplete, side reactions can occur, or material can be lost during handling."]}],"equations":[{"label":"Percent yield","expression":"% yield = actual yield / theoretical yield × 100%"},{"label":"Reaction conversion","expression":"mol B = mol A × (coefficient B / coefficient A)"}],"example":{"prompt":"2 H₂ + O₂ → 2 H₂O. If 5.00 mol H₂ reacts with 2.00 mol O₂, what limits the reaction and how many moles of water can form?","steps":["5.00 mol H₂ would require 2.50 mol O₂, but only 2.00 mol O₂ is available.","Therefore O₂ is limiting.","2.00 mol O₂ × (2 mol H₂O / 1 mol O₂) = 4.00 mol H₂O."],"answer":"O₂ is limiting; theoretical yield = 4.00 mol H₂O"},"check":{"question":"In N₂ + 3H₂ → 2NH₃, how many moles NH₃ form from 6.0 mol H₂ if N₂ is excess?","choices":["2.0 mol","4.0 mol","6.0 mol","12 mol"],"answer":1,"explanation":"6.0 mol H₂ × (2 mol NH₃ / 3 mol H₂) = 4.0 mol NH₃."},"bridge":{"course":"Every reaction-based course","text":"Organic synthesis yield, enzyme turnovers, analytical titrations and metabolic mass balances all rely on conservation and stoichiometric relationships."},"lab":"Directly supports reaction-type experiments, gravimetric work, hydrates, limiting-reactant studies and percent-yield analysis.","tool":null,"vocabulary":["coefficient","mole ratio","limiting reactant","excess reactant","theoretical yield","actual yield","percent yield"]},{"id":"aqueous","semester":1,"number":5,"title":"Aqueous Reactions, Ions & Redox","subtitle":"What changes when substances dissolve and react in water.","prerequisite":"Chemical Reactions & Stoichiometry","outcomes":["Classify strong electrolytes, weak electrolytes and nonelectrolytes","Use solubility patterns to predict precipitation","Write complete and net ionic equations","Assign oxidation numbers and recognize redox reactions"],"sections":[{"title":"Dissolution can create mobile ions","body":["Strong electrolytes dissociate essentially completely into ions in water, making the solution electrically conductive. Weak electrolytes ionize only partially, while nonelectrolytes dissolve without generating appreciable ions.","When writing ionic equations, strong soluble electrolytes are represented as separated ions. Solids, liquids, gases and weak electrolytes remain intact."]},{"title":"Net ionic equations reveal the chemical event","body":["A precipitation reaction occurs when ions combine to form a sparingly soluble solid. Spectator ions appear unchanged on both sides of the complete ionic equation and are removed to obtain the net ionic equation.","Acid–base neutralization can likewise be reduced to the core transfer process. For a strong acid and strong base, H⁺(aq) + OH⁻(aq) → H₂O(l)."]},{"title":"Redox tracks electron transfer","body":["Oxidation is an increase in oxidation number and corresponds to loss of electrons; reduction is a decrease and corresponds to gain of electrons. Oxidizing agents are reduced, while reducing agents are oxidized. This vocabulary becomes the foundation of electrochemistry and the electron-transfer chains of biochemistry."]}],"equations":[{"label":"Molarity","expression":"M = mol solute / L solution"},{"label":"Dilution","expression":"M₁V₁ = M₂V₂"}],"example":{"prompt":"Mix aqueous AgNO₃ and NaCl. Write the net ionic equation.","steps":["Both reactants are soluble strong electrolytes, so write them as ions.","AgCl is insoluble and forms a solid; Na⁺ and NO₃⁻ remain aqueous.","Cancel spectator ions."],"answer":"Ag⁺(aq) + Cl⁻(aq) → AgCl(s)"},"check":{"question":"Which species is oxidized when Zn(s) reacts with Cu²⁺(aq) to form Zn²⁺ and Cu(s)?","choices":["Zn","Cu²⁺","Zn²⁺","Cu"],"answer":0,"explanation":"Zn goes from oxidation state 0 to +2, an increase, so zinc is oxidized."},"bridge":{"course":"Analytical chemistry & biochemistry","text":"Precipitation, acid–base and redox chemistry become titrations, separations, electrodes, cofactors and biological electron transfer."},"lab":"Connects to solubility, reaction classification, separations, conductivity and qualitative observations of precipitates.","tool":null,"vocabulary":["electrolyte","spectator ion","net ionic equation","precipitate","oxidation number","oxidation","reduction"]},{"id":"thermochemistry","semester":1,"number":6,"title":"Thermochemistry & Energy","subtitle":"Tracking energy as reactions change matter.","prerequisite":"Stoichiometry","outcomes":["Define system, surroundings, heat and work","Use sign conventions for energy transfer","Calculate heat with specific heat capacity","Relate reaction enthalpy to stoichiometric amount and use Hess’s law"],"sections":[{"title":"Energy bookkeeping begins with a boundary","body":["The system is the part of the universe chosen for study; everything else is the surroundings. Heat q is energy transferred because of a temperature difference, while work w is energy transferred by other organized processes such as expansion against pressure.","Using the chemistry sign convention, heat entering the system is positive and heat leaving is negative. Work done on the system is positive; work done by the system is negative."]},{"title":"Enthalpy is useful at constant pressure","body":["For many reactions carried out open to the atmosphere, the heat transferred at constant pressure equals the enthalpy change ΔH. An exothermic process has ΔH < 0 and releases heat; an endothermic process has ΔH > 0 and absorbs heat.","Because enthalpy is a state function, the overall ΔH depends only on initial and final states. Hess’s law lets us add known reactions and their enthalpies to construct a target reaction."]},{"title":"Calorimetry converts temperature change into heat","body":["If no phase change or reaction occurs within the measured material, q = mcΔT relates heat to mass, specific heat capacity and temperature change. In an insulated calorimeter, heat lost by one part is approximately heat gained by another."]}],"equations":[{"label":"First law","expression":"ΔE = q + w"},{"label":"Sensible heat","expression":"q = mcΔT"},{"label":"Reaction heat","expression":"qₚ = ΔH at constant pressure"}],"example":{"prompt":"How much heat is needed to warm 100.0 g water from 22.0 °C to 35.0 °C? Use c = 4.184 J g⁻¹ °C⁻¹.","steps":["ΔT = 35.0 − 22.0 = 13.0 °C.","q = (100.0 g)(4.184 J g⁻¹ °C⁻¹)(13.0 °C).","Round to three significant figures."],"answer":"5.44 × 10³ J = 5.44 kJ absorbed"},"check":{"question":"A reaction has ΔH = −125 kJ mol⁻¹. Which statement is correct?","choices":["It is endothermic","It releases heat to the surroundings","The products must be hotter","Entropy must decrease"],"answer":1,"explanation":"Negative ΔH means the system releases heat at constant pressure; the process is exothermic."},"bridge":{"course":"Physical chemistry & metabolism","text":"Thermodynamics later separates enthalpy, entropy and free energy; biochemistry uses the same bookkeeping for ATP hydrolysis and coupled reactions."},"lab":"Connects to energy measurements, calorimetry, hydration/dehydration and careful temperature data interpretation.","tool":null,"vocabulary":["system","surroundings","heat","work","enthalpy","exothermic","endothermic","state function"]},{"id":"electronic","semester":1,"number":7,"title":"Electronic Structure & Quantum Ideas","subtitle":"Why electrons occupy orbitals instead of miniature planetary paths.","prerequisite":"Atoms & the Mole; Energy","outcomes":["Relate wavelength, frequency and photon energy","Explain why line spectra imply quantized energy levels","Interpret principal quantum numbers and orbital types","Write ground-state electron configurations using Aufbau, Pauli and Hund principles"],"sections":[{"title":"Light behaves as both wave and quantized energy","body":["Electromagnetic radiation is characterized by wavelength λ and frequency ν, linked by the speed of light. Planck’s relation E = hν shows that electromagnetic energy is exchanged in packets called photons.","Atomic line spectra occur because atoms absorb or emit only particular photon energies, implying discrete allowed energy differences rather than a continuous range."]},{"title":"Orbitals are probability distributions","body":["The modern quantum model does not assign an electron a definite circular path. An orbital is a mathematical description of where an electron is likely to be found and of its energy. Principal shells are labeled by n; subshells s, p, d and f have characteristic shapes and numbers of orbitals.","Each orbital can hold at most two electrons with opposite spin. Degenerate orbitals within a subshell fill singly before pairing, consistent with Hund’s rule."]},{"title":"Electron configuration predicts chemical behavior","body":["Valence electrons are the electrons most involved in bonding and chemical change. Patterns in valence configuration repeat across the periodic table, which is why elements in the same group often react similarly."]}],"equations":[{"label":"Wave relation","expression":"c = λν"},{"label":"Photon energy","expression":"E = hν = hc/λ"}],"example":{"prompt":"Write the ground-state electron configuration of phosphorus, Z = 15.","steps":["Fill orbitals in increasing-energy order.","1s² 2s² 2p⁶ accounts for 10 electrons.","Place the remaining 5 as 3s² 3p³; the three 3p electrons occupy separate p orbitals before pairing."],"answer":"1s² 2s² 2p⁶ 3s² 3p³"},"check":{"question":"How many orbitals are in a p subshell?","choices":["1","2","3","6"],"answer":2,"explanation":"A p subshell contains three orbitals. Each orbital can contain up to two electrons, so a p subshell can hold six electrons total."},"bridge":{"course":"Organic, inorganic & spectroscopy","text":"Orbitals explain bonding, conjugation, transition-metal chemistry, UV/Vis spectroscopy and the electronic basis of molecular structure."},"lab":"Connects to emission spectra, quantitative graphing and the interpretation of discrete spectral lines.","tool":null,"vocabulary":["wavelength","frequency","photon","orbital","subshell","electron configuration","Pauli principle","Hund rule"]},{"id":"periodic","semester":1,"number":8,"title":"Periodic Trends & Effective Nuclear Charge","subtitle":"Using electron structure to predict how atoms behave.","prerequisite":"Electronic Structure","outcomes":["Explain shielding and effective nuclear charge qualitatively","Predict atomic and ionic radius trends","Explain first-ionization-energy trends and common exceptions","Relate electronegativity to bond polarity"],"sections":[{"title":"The periodic table is an electron-structure map","body":["Across a period, nuclear charge increases while added electrons enter the same principal shell. Shielding does not increase enough to cancel the added proton attraction, so effective nuclear charge generally rises and atomic radius decreases.","Down a group, electrons occupy higher principal shells farther from the nucleus, so atomic size usually increases despite the greater nuclear charge."]},{"title":"Removing an electron requires energy","body":["Ionization energy is the energy required to remove an electron from a gas-phase species. It generally increases across a period and decreases down a group. Deviations are informative: they reflect subshell energies and electron pairing rather than invalidating the trend.","Large jumps between successive ionization energies can reveal how many valence electrons were relatively easy to remove."]},{"title":"Electronegativity forecasts unequal electron sharing","body":["Electronegativity describes an atom’s tendency to attract shared electrons in a bond. A difference in electronegativity creates bond polarity, but molecular polarity also depends on geometry and whether individual bond dipoles cancel."]}],"equations":[{"label":"Conceptual effective charge","expression":"Z_eff ≈ Z − shielding"}],"example":{"prompt":"Which is larger, Na or Na⁺, and why?","steps":["Na loses its 3s valence electron to form Na⁺.","The cation has one fewer occupied shell and less electron–electron repulsion.","The remaining electrons experience stronger effective attraction per electron."],"answer":"Na is larger than Na⁺."},"check":{"question":"Which atom is expected to have the larger first ionization energy?","choices":["Na","Mg","K","Rb"],"answer":1,"explanation":"Among these choices, Mg is farther right and in a smaller principal shell than K or Rb; its valence electron is held more strongly."},"bridge":{"course":"Organic reactivity & biochemistry","text":"Electronegativity and size become nucleophilicity, acidity, bond polarization, hydrogen bonding and metal-ion behavior."},"lab":null,"tool":null,"vocabulary":["shielding","effective nuclear charge","atomic radius","ionic radius","ionization energy","electron affinity","electronegativity"]},{"id":"bonding","semester":1,"number":9,"title":"Bonding, Lewis Structures & Resonance","subtitle":"From valence electrons to stable connectivity.","prerequisite":"Periodic Trends","outcomes":["Differentiate ionic, polar covalent and nonpolar covalent bonding models","Construct Lewis structures from total valence-electron counts","Use formal charge to compare plausible structures","Represent resonance without treating contributors as rapidly switching molecules"],"sections":[{"title":"Bonding lowers the energy of an arrangement","body":["Ionic bonding emphasizes electrostatic attraction between oppositely charged ions, while covalent bonding emphasizes shared electron density between nuclei. Real bonds often lie on a continuum, and electronegativity difference helps predict where shared electrons are concentrated.","Bond strength and length reflect the balance of attractive and repulsive interactions. Higher bond order generally correlates with shorter, stronger bonds for comparable atom pairs."]},{"title":"Lewis structures are electron-accounting models","body":["Begin by counting total valence electrons, including charge. Choose a reasonable skeleton, add bonds, complete terminal-atom octets and place remaining electrons on the central atom. If the central atom lacks an octet, multiple bonds may be required.","Formal charge is bookkeeping, not a measured partial charge. Useful structures often minimize formal-charge magnitude and place negative formal charge on more electronegative atoms when other factors are comparable."]},{"title":"Resonance describes delocalization","body":["When more than one valid Lewis structure differs only in electron placement, the actual electronic structure is a resonance hybrid. The atoms do not jump between contributors; electron density is delocalized. Resonance becomes one of the most important ideas in organic chemistry and biochemistry."]}],"equations":[{"label":"Formal charge","expression":"FC = valence e⁻ − nonbonding e⁻ − ½(bonding e⁻)"},{"label":"Bond order idea","expression":"higher bond order → usually shorter, stronger bond"}],"example":{"prompt":"Find the formal charge on nitrogen in NH₄⁺.","steps":["Nitrogen has 5 valence electrons.","In NH₄⁺, N has no nonbonding electrons and 8 bonding electrons.","FC = 5 − 0 − ½(8) = +1."],"answer":"Formal charge on N = +1"},"check":{"question":"Which statement about resonance is correct?","choices":["The molecule rapidly switches between Lewis structures","Atoms move to new positions in each contributor","The real structure is a delocalized hybrid","Resonance only occurs in ions"],"answer":2,"explanation":"Resonance contributors are bookkeeping representations of one delocalized electronic structure."},"bridge":{"course":"Organic chemistry","text":"Formal charge, resonance and bond polarization are the language of curved-arrow mechanisms, aromaticity, acidity and carbonyl chemistry."},"lab":"Supports solubility trends, structure–property reasoning and molecular-model interpretation.","tool":null,"vocabulary":["ionic bond","covalent bond","Lewis structure","octet rule","formal charge","resonance","bond order"]},{"id":"geometry","semester":1,"number":10,"title":"Molecular Geometry, Polarity & Bonding Models","subtitle":"Turning a flat Lewis structure into a three-dimensional molecule.","prerequisite":"Bonding & Lewis Structures","outcomes":["Use electron-domain count to predict electron geometry","Distinguish electron geometry from molecular geometry","Predict approximate bond angles and lone-pair distortions","Combine bond dipoles as vectors to predict molecular polarity","Recognize σ/π bonding and introductory hybridization models"],"sections":[{"title":"Electron domains arrange in three dimensions","body":["VSEPR treats regions of valence electron density as repelling one another. Two domains favor linear separation, three trigonal planar, four tetrahedral, five trigonal bipyramidal and six octahedral. A multiple bond counts as one domain for geometry.","Molecular geometry names the positions of atoms, so lone pairs can cause molecular geometry to differ from electron geometry. Lone pairs generally repel more strongly than bonding pairs and compress nearby bond angles."]},{"title":"Bond polarity does not automatically mean molecular polarity","body":["A polar bond has unequal electron sharing and therefore a bond dipole. Molecular polarity is the vector sum of all bond dipoles and depends on three-dimensional arrangement. CO₂ contains polar C=O bonds but is nonpolar because its equal dipoles oppose perfectly in a linear geometry. Water is polar because its bent geometry prevents cancellation."]},{"title":"σ and π models prepare you for organic chemistry","body":["A single bond is described as one σ bond. Double bonds contain one σ and one π bond; triple bonds contain one σ and two π bonds. Introductory hybridization labels sp, sp² and sp³ connect electron-domain geometry to directional bonding, although more advanced courses refine this model."]}],"equations":[{"label":"Dipole concept","expression":"molecular dipole = vector sum of bond dipoles"},{"label":"Bond components","expression":"single: 1σ • double: 1σ + 1π • triple: 1σ + 2π"}],"example":{"prompt":"Predict the geometry and polarity of NH₃.","steps":["Nitrogen has three N–H bonds and one lone pair: four electron domains.","Four domains give tetrahedral electron geometry; ignoring the lone pair gives trigonal-pyramidal molecular geometry.","The N–H bond dipoles do not cancel in a trigonal-pyramidal shape."],"answer":"Trigonal pyramidal; polar"},"check":{"question":"Which molecule is nonpolar because its bond dipoles cancel by symmetry?","choices":["H₂O","NH₃","CO₂","SO₂"],"answer":2,"explanation":"CO₂ is linear with two equal C=O dipoles in opposite directions."},"bridge":{"course":"Organic chemistry & biochemistry","text":"Shape controls stereochemistry, orbital overlap, receptor binding, protein folding and whether a reactive group can physically approach another."},"lab":"Directly paired with ChemWaypoint’s interactive VSEPR Model Lab.","tool":{"label":"Open 3D VSEPR Model Lab","action":"lab"},"vocabulary":["electron domain","electron geometry","molecular geometry","bond dipole","molecular polarity","sigma bond","pi bond","hybridization"]},{"id":"gases","semester":1,"number":11,"title":"Gases & Kinetic Molecular Theory","subtitle":"A quantitative model for particles in constant motion.","prerequisite":"Stoichiometry; Thermochemistry","outcomes":["Relate pressure, volume, temperature and amount","Apply the ideal gas law with consistent units","Use Dalton’s law for gas mixtures","Connect macroscopic gas behavior to particle motion using kinetic molecular theory"],"sections":[{"title":"Gas variables are strongly coupled","body":["Gas pressure comes from molecular collisions with container walls. Increasing temperature raises average molecular kinetic energy, while changing volume changes how frequently particles strike the walls.","The ideal gas law combines the relationships among pressure P, volume V, amount n and absolute temperature T. Temperature must be expressed in kelvin because gas-law proportionalities are anchored to absolute zero."]},{"title":"Mixture pressure is additive for ideal gases","body":["Dalton’s law states that total pressure is the sum of component partial pressures. A gas’s partial pressure is proportional to its mole fraction in an ideal mixture. This idea becomes useful in respiration, gas collection and equilibrium systems."]},{"title":"Kinetic molecular theory explains the equations","body":["The ideal model assumes particles occupy negligible volume, experience negligible intermolecular attractions and collide elastically. Real gases deviate most when particles are crowded at high pressure or attractions become important at low temperature."]}],"equations":[{"label":"Ideal gas law","expression":"PV = nRT"},{"label":"Dalton’s law","expression":"P_total = ΣPᵢ"},{"label":"Mole fraction pressure","expression":"Pᵢ = χᵢP_total"}],"example":{"prompt":"What volume does 0.500 mol ideal gas occupy at 1.00 atm and 298 K? Use R = 0.082057 L·atm·mol⁻¹·K⁻¹.","steps":["Rearrange PV = nRT to V = nRT/P.","V = (0.500)(0.082057)(298)/(1.00).","Round to three significant figures."],"answer":"12.2 L"},"check":{"question":"At constant amount and volume, what happens to ideal-gas pressure when Kelvin temperature doubles?","choices":["It halves","It stays constant","It doubles","It quadruples"],"answer":2,"explanation":"From PV = nRT, with n and V fixed, P is directly proportional to absolute temperature."},"bridge":{"course":"Physical chemistry & biochemistry","text":"Gas behavior leads into statistical mechanics, thermodynamics, respiration, oxygen transport and partial-pressure-driven processes."},"lab":"Directly connects to the UArk majors-lab gas-law emphasis and quantitative data interpretation.","tool":null,"vocabulary":["pressure","ideal gas","partial pressure","mole fraction","kinetic molecular theory","absolute temperature"]},{"id":"imf","semester":2,"number":12,"title":"Intermolecular Forces, Liquids & Solids","subtitle":"Why molecules with similar bonds can have very different bulk properties.","prerequisite":"Molecular Geometry & Polarity","outcomes":["Distinguish intramolecular bonds from intermolecular attractions","Identify London dispersion, dipole–dipole and hydrogen-bonding interactions","Relate intermolecular forces to boiling point, viscosity and vapor pressure","Interpret heating curves and phase diagrams"],"sections":[{"title":"Intermolecular attractions act between particles","body":["Covalent or ionic bonds hold atoms together within a substance; intermolecular forces act between molecules or particles. Breaking intermolecular attractions during boiling does not break the covalent bonds within each molecule.","All atoms and molecules experience London dispersion forces arising from temporary fluctuations in electron distribution. Larger, more polarizable electron clouds usually generate stronger dispersion."]},{"title":"Polarity adds directional attractions","body":["Polar molecules experience dipole–dipole attractions. Hydrogen bonding is a particularly strong, directional interaction when H is covalently bonded to N, O or F and interacts with a lone pair on a suitable partner.","Stronger intermolecular attractions generally raise boiling point and viscosity while lowering vapor pressure at a given temperature."]},{"title":"Phase changes balance energy and molecular freedom","body":["Melting, vaporization and sublimation are endothermic because energy is required to overcome attractions. During a phase change at constant pressure, added heat changes the phase rather than the temperature until the transition is complete."]}],"equations":[{"label":"Phase-change heat","expression":"q = nΔH_phase"},{"label":"Heating within a phase","expression":"q = mcΔT"}],"example":{"prompt":"Why does water boil at a much higher temperature than H₂S even though both are group-16 hydrides?","steps":["Both have dispersion interactions.","Water molecules can form an extensive hydrogen-bond network because O–H bonds are highly polar and oxygen has lone pairs.","H₂S does not form comparably strong classical hydrogen bonding."],"answer":"Stronger hydrogen bonding in water requires more energy to separate molecules into the gas phase."},"check":{"question":"Which change generally accompanies stronger intermolecular forces?","choices":["Higher vapor pressure","Lower boiling point","Higher boiling point","Lower viscosity"],"answer":2,"explanation":"Stronger attractions require more energy for molecules to escape into the gas phase, so boiling point tends to rise."},"bridge":{"course":"Organic & biochemistry","text":"Solubility, chromatographic retention, membrane formation, protein folding and drug binding all depend on competing intermolecular interactions."},"lab":null,"tool":null,"vocabulary":["London dispersion","dipole–dipole","hydrogen bonding","polarizability","vapor pressure","phase diagram"]},{"id":"solutions","semester":2,"number":13,"title":"Solutions, Concentration & Colligative Properties","subtitle":"What determines how much dissolves and what dissolved particles do.","prerequisite":"Intermolecular Forces","outcomes":["Use molarity, molality and mole fraction appropriately","Explain “like dissolves like” in terms of competing interactions","Apply dilution and solution-stoichiometry relationships","Predict qualitative colligative-property changes"],"sections":[{"title":"Dissolving requires favorable competition","body":["For a solution to form, solute–solute and solvent–solvent attractions are disrupted and replaced by solute–solvent attractions. “Like dissolves like” is shorthand for matching interaction types, not a universal law.","Ionic solutes can dissolve in polar solvents when ion–dipole stabilization compensates for separating ions from the crystal lattice."]},{"title":"Concentration can be expressed several ways","body":["Molarity uses moles of solute per liter of solution and is convenient for volumetric chemistry, but it changes slightly with temperature because volume changes. Molality uses moles per kilogram of solvent and is temperature independent."]},{"title":"Colligative properties count dissolved particles","body":["Ideal colligative effects depend primarily on the number of dissolved particles, not their identity. Nonvolatile solutes lower vapor pressure, elevate boiling point and depress freezing point. Electrolytes can generate multiple ions, represented approximately by the van’t Hoff factor i."]}],"equations":[{"label":"Molarity","expression":"M = mol solute / L solution"},{"label":"Molality","expression":"m = mol solute / kg solvent"},{"label":"Freezing-point depression","expression":"ΔT_f = iK_fm"}],"example":{"prompt":"How many moles NaCl are in 250.0 mL of 0.200 M NaCl?","steps":["Convert 250.0 mL to 0.2500 L.","mol = M × V = 0.200 mol/L × 0.2500 L."],"answer":"0.0500 mol NaCl"},"check":{"question":"Which solution ideally has the greatest freezing-point depression at the same molality?","choices":["Glucose","NaCl","CaCl₂","All are identical"],"answer":2,"explanation":"CaCl₂ ideally produces about three ions per formula unit, giving the largest particle count and largest colligative effect."},"bridge":{"course":"Analytical chemistry & biochemistry","text":"Concentration units underpin buffers, assays, standard solutions, osmotic effects and preparation of biological media."},"lab":"Closely connected to freezing-point depression, solubility and solution preparation.","tool":null,"vocabulary":["molarity","molality","mole fraction","solvation","colligative property","van’t Hoff factor","osmosis"]},{"id":"kinetics","semester":2,"number":14,"title":"Chemical Kinetics","subtitle":"How fast reactions happen and what controls the rate.","prerequisite":"Stoichiometry; Energy","outcomes":["Define reaction rate from concentration change","Determine rate-law form from experimental data","Use integrated rate laws for common reaction orders","Interpret activation energy and catalysts using collision/transition-state ideas"],"sections":[{"title":"Thermodynamic possibility and kinetic speed are different questions","body":["A reaction can be energetically favorable yet proceed extremely slowly because reactants must cross an activation barrier. Kinetics studies how concentration changes with time and which molecular events control that rate.","Reaction rate is normalized by stoichiometric coefficient so disappearance and appearance rates describe one consistent reaction progress."]},{"title":"Rate laws are empirical","body":["A rate law such as rate = k[A]^m[B]^n must be determined experimentally for a reaction mechanism under given conditions. The exponents are reaction orders and are not generally obtained from the overall balanced equation.","Integrated rate laws relate concentration directly to time. A first-order process gives a linear plot of ln[A] versus time and has a concentration-independent half-life."]},{"title":"Catalysts lower the kinetic barrier","body":["A catalyst provides an alternative reaction pathway with lower activation energy and speeds both forward and reverse reactions. It does not change the reaction’s equilibrium constant or overall thermodynamic driving force."]}],"equations":[{"label":"General rate law","expression":"rate = k[A]^m[B]^n"},{"label":"First-order integrated law","expression":"ln[A]ₜ = ln[A]₀ − kt"},{"label":"Arrhenius equation","expression":"k = Ae^(−Eₐ/RT)"}],"example":{"prompt":"A first-order reaction has k = 0.0350 min⁻¹. What is its half-life?","steps":["For a first-order reaction, t₁/₂ = ln2/k.","0.693 / 0.0350 min⁻¹ = 19.8 min."],"answer":"19.8 min"},"check":{"question":"What does a catalyst change?","choices":["ΔG° of reaction","Equilibrium constant","Activation energy","Stoichiometric coefficients"],"answer":2,"explanation":"A catalyst changes the pathway and lowers activation energy without changing the initial/final thermodynamic states."},"bridge":{"course":"Physical chemistry & enzyme kinetics","text":"Mechanistic kinetics becomes reaction dynamics in physical chemistry and Michaelis–Menten/catalytic reasoning in biochemistry."},"lab":null,"tool":null,"vocabulary":["reaction rate","rate law","reaction order","rate constant","half-life","activation energy","catalyst"]},{"id":"equilibrium","semester":2,"number":15,"title":"Chemical Equilibrium","subtitle":"Dynamic balance and the reaction quotient.","prerequisite":"Kinetics","outcomes":["Explain equilibrium as a dynamic state","Write equilibrium-constant expressions","Use Q versus K to predict direction of change","Apply ICE-table reasoning to simple equilibrium calculations","Use Le Châtelier’s principle as a qualitative consequence of Q and K"],"sections":[{"title":"Equilibrium is dynamic, not static","body":["At equilibrium, forward and reverse reaction rates are equal, so macroscopic concentrations remain constant even though molecular reactions continue. Equal rates do not imply equal concentrations.","The equilibrium constant K relates activities or, in introductory approximations, equilibrium concentrations or partial pressures raised to stoichiometric powers. Pure solids and liquids are omitted from common K expressions."]},{"title":"Q tells where the system is right now","body":["The reaction quotient Q has the same form as K but uses current, not necessarily equilibrium, composition. If Q < K, the system proceeds forward; if Q > K, it proceeds in reverse; if Q = K, it is at equilibrium."]},{"title":"Disturbances change composition, not K unless temperature changes","body":["Adding a reactant, removing a product or changing volume can make Q differ from K, causing the system to shift until Q returns to K. For a given reaction, only temperature changes K itself. This is the quantitative foundation underneath Le Châtelier’s principle."]}],"equations":[{"label":"Generic concentration equilibrium","expression":"K_c = [products]^coeff / [reactants]^coeff"},{"label":"Direction test","expression":"Q < K → forward • Q > K → reverse"}],"example":{"prompt":"For A ⇌ B, K = 4.0. If [A] = 1.0 M and [B] = 1.0 M, which direction will the system initially shift?","steps":["Q = [B]/[A] = 1.0.","Compare Q = 1.0 with K = 4.0.","Because Q < K, more products must form."],"answer":"The reaction shifts forward, toward B."},"check":{"question":"Which change alters the numerical value of K for a given reaction?","choices":["Adding reactant","Removing product","Changing container volume","Changing temperature"],"answer":3,"explanation":"Composition or volume changes can shift the system, but K itself changes with temperature."},"bridge":{"course":"Biochemistry & analytical chemistry","text":"Binding, acid–base behavior, metal complexation, enzyme equilibria and coupled biochemical reactions all use equilibrium logic."},"lab":null,"tool":null,"vocabulary":["dynamic equilibrium","equilibrium constant","reaction quotient","ICE table","Le Châtelier principle"]},{"id":"acidbase","semester":2,"number":16,"title":"Acids, Bases & Buffers","subtitle":"Proton transfer, pH and chemical resistance to change.","prerequisite":"Chemical Equilibrium","outcomes":["Use Brønsted–Lowry acid/base definitions","Relate Ka, Kb, pKa and conjugate strength","Calculate pH for common strong and weak acid/base cases","Explain buffer action and use Henderson–Hasselbalch appropriately","Interpret titration regions qualitatively"],"sections":[{"title":"Acid–base reactions are proton-transfer equilibria","body":["A Brønsted acid donates H⁺ and a Brønsted base accepts H⁺. Every acid has a conjugate base formed after proton donation, and every base has a conjugate acid formed after proton acceptance.","Strong acids are treated as essentially fully ionized in dilute water, while weak acids establish equilibria described by Ka. A smaller pKa corresponds to a stronger acid."]},{"title":"pH compresses a huge concentration range","body":["pH = −log[H₃O⁺] converts hydronium concentration into a manageable logarithmic scale. At 25 °C, Kw = 1.0 × 10⁻¹⁴ and pH + pOH = 14.00 for ideal dilute aqueous solutions."]},{"title":"Buffers use a weak acid/base pair as a reservoir","body":["A buffer contains appreciable amounts of a weak acid and its conjugate base, or a weak base and conjugate acid. Added H⁺ is consumed primarily by the base component; added OH⁻ is consumed by the acid component.","The Henderson–Hasselbalch equation is most useful when both conjugate partners are present in meaningful amounts. Near pH = pKa, buffer capacity is typically effective and the acid/base ratio is near one."]}],"equations":[{"label":"Acid dissociation","expression":"Kₐ = [H₃O⁺][A⁻] / [HA]"},{"label":"pH","expression":"pH = −log[H₃O⁺]"},{"label":"Henderson–Hasselbalch","expression":"pH = pKₐ + log([A⁻]/[HA])"}],"example":{"prompt":"A buffer has equal concentrations of acetic acid and acetate. If pKa = 4.76, what is the pH?","steps":["Use Henderson–Hasselbalch.","[A⁻]/[HA] = 1, and log(1) = 0.","Therefore pH = pKa."],"answer":"pH = 4.76"},"check":{"question":"If pH is one unit above pKa, which form predominates?","choices":["Protonated acid HA by 10:1","Conjugate base A⁻ by 10:1","They are equal","Cannot be determined"],"answer":1,"explanation":"pH − pKa = 1 = log([A⁻]/[HA]), so [A⁻]/[HA] = 10."},"bridge":{"course":"Biochemistry","text":"Protein charge, enzyme catalysis, amino-acid ionization, DNA chemistry and physiological buffering are direct extensions of this module."},"lab":null,"tool":null,"vocabulary":["Brønsted acid","Brønsted base","conjugate pair","Ka","pKa","pH","buffer","titration"]},{"id":"solubility","semester":2,"number":17,"title":"Solubility & Coupled Equilibria","subtitle":"When precipitation, complexation and acid–base chemistry compete.","prerequisite":"Equilibrium; Acids & Bases","outcomes":["Write Ksp expressions","Use ion products to predict precipitation","Apply common-ion reasoning","Recognize how pH and complex formation can change apparent solubility"],"sections":[{"title":"Sparingly soluble solids establish equilibria","body":["A salt can be described by a dissolution equilibrium between the solid and its dissolved ions. The solubility-product constant Ksp contains only dissolved species because the pure solid’s activity is treated as constant.","Comparing the ionic reaction quotient Qsp with Ksp predicts whether a solution is unsaturated, saturated or supersaturated with respect to a solid."]},{"title":"Equilibria couple to one another","body":["If one dissolved ion is consumed by another equilibrium, dissolution can be pulled forward. For example, salts containing basic anions may become more soluble in acid because protonation removes the free anion from solution.","Complex-ion formation can similarly stabilize a dissolved metal ion, changing apparent solubility. This network perspective is more powerful than memorizing isolated “solubility rules.”"]}],"equations":[{"label":"Example Ksp","expression":"MX(s) ⇌ M⁺ + X⁻ ; Ksp = [M⁺][X⁻]"},{"label":"Precipitation test","expression":"Qsp > Ksp → precipitation favored"}],"example":{"prompt":"For AgCl, Ksp = 1.8 × 10⁻¹⁰. In pure water, approximate the molar solubility s.","steps":["AgCl(s) ⇌ Ag⁺ + Cl⁻.","In pure water, [Ag⁺] = [Cl⁻] = s.","Ksp = s², so s = √(1.8 × 10⁻¹⁰)."],"answer":"s ≈ 1.34 × 10⁻⁵ M"},"check":{"question":"Adding NaCl to a saturated AgCl solution generally does what to AgCl solubility?","choices":["Increases it","Decreases it","Leaves it unchanged","Makes Ksp larger"],"answer":1,"explanation":"Added Cl⁻ is a common ion, increasing Qsp and shifting the dissolution equilibrium toward solid AgCl. Ksp itself is unchanged at fixed temperature."},"bridge":{"course":"Analytical & inorganic chemistry","text":"Selective precipitation, complexometric analysis and metal-ion speciation require coupled-equilibrium reasoning."},"lab":null,"tool":null,"vocabulary":["Ksp","molar solubility","common-ion effect","ion product","complex ion","coupled equilibrium"]},{"id":"thermodynamics","semester":2,"number":18,"title":"Entropy, Free Energy & Spontaneity","subtitle":"Why some energetically costly processes can still proceed.","prerequisite":"Thermochemistry; Equilibrium","outcomes":["Interpret entropy as dispersal/multiplicity rather than “disorder” alone","Use qualitative entropy trends","Relate ΔG, ΔH and ΔS","Connect standard free energy to equilibrium constants","Distinguish thermodynamic favorability from reaction rate"],"sections":[{"title":"Entropy tracks energy and matter dispersal","body":["Entropy S is connected to the number of microscopic arrangements compatible with a macroscopic state. Processes that increase the number of accessible arrangements often have positive ΔS. Gas formation, mixing and greater molecular freedom commonly increase entropy.","“Disorder” can be a useful first intuition but is too vague for careful reasoning; the statistical interpretation is more reliable."]},{"title":"Gibbs free energy combines enthalpy and entropy","body":["At constant temperature and pressure, ΔG = ΔH − TΔS predicts thermodynamic direction. ΔG < 0 indicates a forward process is favorable under the specified conditions; ΔG > 0 favors the reverse; ΔG = 0 corresponds to equilibrium.","A favorable ΔG says nothing about how fast a process occurs. Diamond converting to graphite is thermodynamically favorable under ordinary conditions but kinetically extremely slow."]},{"title":"Free energy and equilibrium are the same story","body":["Standard free energy and the equilibrium constant are linked by ΔG° = −RT ln K. A large K corresponds to negative ΔG° and product-favored standard equilibrium, while a small K corresponds to positive ΔG°."]}],"equations":[{"label":"Gibbs free energy","expression":"ΔG = ΔH − TΔS"},{"label":"Free energy & equilibrium","expression":"ΔG° = −RT ln K"}],"example":{"prompt":"At 298 K, a process has ΔH = +20.0 kJ/mol and ΔS = +100 J mol⁻¹ K⁻¹. Estimate ΔG.","steps":["Convert ΔS to 0.100 kJ mol⁻¹ K⁻¹.","TΔS = (298)(0.100) = 29.8 kJ/mol.","ΔG = 20.0 − 29.8 = −9.8 kJ/mol."],"answer":"ΔG ≈ −9.8 kJ/mol; favorable under these conditions"},"check":{"question":"A reaction with ΔG° < 0 necessarily has what property?","choices":["It is fast","K > 1","ΔH < 0","No activation barrier"],"answer":1,"explanation":"ΔG° = −RT lnK. If ΔG° is negative, lnK is positive and K > 1. Rate is a kinetic question."},"bridge":{"course":"Physical chemistry & biochemistry","text":"This becomes chemical potential and statistical thermodynamics in p-chem, and reaction coupling/ATP energetics in biochemistry."},"lab":null,"tool":null,"vocabulary":["entropy","microstate","Gibbs free energy","spontaneity","standard state","reaction coupling"]},{"id":"electrochem","semester":2,"number":19,"title":"Electrochemistry","subtitle":"Turning redox chemistry into electrical work.","prerequisite":"Redox; Thermodynamics","outcomes":["Write oxidation and reduction half-reactions","Identify anode, cathode and electron-flow direction","Calculate standard cell potential from reduction potentials","Relate cell potential to free energy and equilibrium","Use the Nernst equation conceptually for nonstandard conditions"],"sections":[{"title":"Electrochemical cells spatially separate redox half-reactions","body":["Oxidation occurs at the anode and reduction at the cathode in both galvanic and electrolytic cells. In a spontaneous galvanic cell, electrons travel through the external circuit from anode to cathode.","A salt bridge or porous separator maintains charge balance by allowing ion migration without directly mixing the half-cell solutions too quickly."]},{"title":"Cell potential measures driving force per charge","body":["Standard reduction potentials are tabulated for half-reactions written as reductions. For a chosen spontaneous cell, E°cell = E°cathode − E°anode. A positive E°cell corresponds to negative ΔG° for the cell reaction.","The Nernst equation shows how potential changes as composition moves away from standard-state conditions and approaches equilibrium."]},{"title":"Redox connects chemistry to biology and technology","body":["Batteries, corrosion, electroplating, sensors and biological electron transport all operate by controlling where oxidation and reduction occur. The mitochondrial electron transport chain can be viewed as a sequence of coupled redox steps that convert electron-transfer free energy into a proton gradient."]}],"equations":[{"label":"Standard cell potential","expression":"E°cell = E°cathode − E°anode"},{"label":"Electrical free energy","expression":"ΔG° = −nFE°cell"},{"label":"Nernst form","expression":"E = E° − (RT/nF) ln Q"}],"example":{"prompt":"Given E°red(Cu²⁺/Cu) = +0.34 V and E°red(Zn²⁺/Zn) = −0.76 V, find E°cell for Zn | Zn²⁺ || Cu²⁺ | Cu.","steps":["Cu²⁺ is reduced at the cathode; Zn is oxidized at the anode.","E°cell = E°cathode − E°anode.","0.34 − (−0.76) = 1.10 V."],"answer":"E°cell = +1.10 V"},"check":{"question":"In a spontaneous galvanic cell, electrons flow through the wire from…","choices":["cathode to anode","anode to cathode","salt bridge to cathode","solution to salt bridge"],"answer":1,"explanation":"Oxidation at the anode produces electrons; reduction at the cathode consumes them."},"bridge":{"course":"Biochemistry & analytical chemistry","text":"Electrodes become potentiometric sensors in analytical chemistry; redox potentials organize electron transfer through NADH, flavins, quinones and respiratory complexes in biochemistry."},"lab":null,"tool":null,"vocabulary":["anode","cathode","galvanic cell","electrolytic cell","cell potential","reduction potential","Nernst equation"]}]};
const BASE_BANKS={"measurement":[{"question":"Which quantity includes both a number and a unit?","choices":["25","25 mL","mL","approximately"],"answer":1,"explanation":"A measurement reports a numerical value and its unit.","id":"measurement-1","level":"Recognize","section":0},{"question":"Repeated measurements are close together but far from a known reference. They are…","choices":["accurate only","precise only","both accurate and precise","neither"],"answer":1,"explanation":"Precision describes agreement among repeated measurements; accuracy describes agreement with a reference.","id":"measurement-2","level":"Explain","section":1},{"question":"Which result correctly reports 12.51 g ÷ 3.2 mL?","choices":["3.909 g/mL","3.91 g/mL","3.9 g/mL","4 g/mL"],"answer":2,"explanation":"Division is limited by the factor with the fewest significant figures. 3.2 has two significant figures, so the result is 3.9 g/mL.","id":"measurement-3","level":"Apply","section":1},{"question":"Convert 0.0250 L to milliliters.","choices":["0.0000250 mL","0.250 mL","25.0 mL","250 mL"],"answer":2,"explanation":"0.0250 L × (1000 mL / 1 L) = 25.0 mL. The conversion factor is exact; preserve three significant figures.","id":"measurement-4","level":"Reason","section":2},{"question":"A sample has mass 10.0 g and volume 5.00 mL. Which setup gives density and explains why?","choices":["5.00 mL / 10.0 g; density is volume per mass","10.0 g × 5.00 mL; multiply all measurements","10.0 g / 5.00 mL; density is mass per volume","10.0 g + 5.00 mL; add the units"],"answer":2,"explanation":"Density is mass per volume: 2.00 g/mL. Unit analysis checks whether a calculation answers the physical question.","callback":{"moduleId":"measurement","section":2},"id":"measurement-5","level":"Connect","section":2},{"question":"A 15.0 g sample occupies 3.0 mL. Report its density.","choices":["5.0 g/mL","5.00 g/mL","0.20 g/mL","45 g/mL"],"answer":0,"explanation":"15.0 / 3.0 = 5.0 g/mL, limited to two significant figures.","id":"measurement-6","level":"Reinforce","section":2}],"atoms-moles":[{"question":"An ion has 17 protons and 18 electrons. What is its charge?","choices":["+1","0","−1","−17"],"answer":2,"explanation":"One more electron than protons gives a net charge of −1. An atom with 17 protons is chlorine, so the ion is Cl⁻.","id":"atoms-moles-1","level":"Recognize","section":0},{"question":"Why are carbon-12 and carbon-14 both carbon?","choices":["Same neutron count","Same proton count","Same mass number","Same number of neutrons and electrons"],"answer":1,"explanation":"An element is defined by its proton count. Isotopes differ in neutron count.","id":"atoms-moles-2","level":"Explain","section":0},{"question":"How many moles are in 24.0 g of carbon if its molar mass is 12.0 g/mol?","choices":["0.500 mol","2.00 mol","12.0 mol","288 mol"],"answer":1,"explanation":"24.0 g × (1 mol / 12.0 g) = 2.00 mol.","callback":{"moduleId":"measurement","section":2},"id":"atoms-moles-3","level":"Apply","section":2},{"question":"An element is 75% isotope X (mass 10 u) and 25% isotope Y (mass 12 u). Its average mass is…","choices":["10.0 u","10.5 u","11.0 u","12.0 u"],"answer":1,"explanation":"Use the weighted average: 0.75 × 10 + 0.25 × 12 = 10.5 u.","id":"atoms-moles-4","level":"Reason","section":1},{"question":"Which conversion correctly counts atoms in 2.00 mol of a monatomic element?","choices":["Divide by Avogadro’s constant","Multiply by molar mass only","Multiply by 6.022 × 10²³ atoms/mol","Multiply by the atomic number"],"answer":2,"explanation":"The mole unit cancels, leaving atoms: about 1.20 × 10²⁴ atoms. This reuses dimensional analysis.","callback":{"moduleId":"measurement","section":2},"id":"atoms-moles-5","level":"Connect","section":2},{"question":"A neutral atom has 12 protons and 13 neutrons. Its mass number is…","choices":["1","12","13","25"],"answer":3,"explanation":"Mass number counts protons plus neutrons: 12 + 13 = 25.","id":"atoms-moles-6","level":"Reinforce","section":0}],"formulas":[{"question":"Which formula represents an ionic compound?","choices":["CO₂","NaCl","CH₄","O₂"],"answer":1,"explanation":"NaCl consists of sodium cations and chloride anions; the other choices are molecular substances.","id":"formulas-1","level":"Recognize","section":0},{"question":"Why is FeCl₃ named iron(III) chloride?","choices":["There are three iron atoms","Iron has a +3 charge in this compound","Chlorine has a +3 charge","The Roman numeral is the total atom count"],"answer":1,"explanation":"Each chloride is −1. Three chlorides require Fe³⁺ for a neutral formula.","id":"formulas-2","level":"Explain","section":1},{"question":"What is the correct formula for aluminum oxide?","choices":["AlO","Al₂O","AlO₂","Al₂O₃"],"answer":3,"explanation":"Al forms Al³⁺ and oxide is O²⁻. The lowest neutral combination is 2 Al³⁺ and 3 O²⁻, giving Al₂O₃.","id":"formulas-3","level":"Apply","section":0},{"question":"What is the formula for calcium nitrate?","choices":["CaNO₃","Ca₂NO₃","Ca(NO₃)₂","Ca₂(NO₃)₃"],"answer":2,"explanation":"Ca²⁺ requires two NO₃⁻ ions. Parentheses keep the polyatomic ion intact.","id":"formulas-4","level":"Reason","section":1},{"question":"A sample contains 0.10 mol C and 0.20 mol H atoms. What empirical formula follows?","choices":["CH","CH₂","C₂H","C₂H₂"],"answer":1,"explanation":"Divide both mole amounts by 0.10 to find the simplest atom ratio, 1:2.","callback":{"moduleId":"atoms-moles","section":2},"id":"formulas-5","level":"Connect","section":2},{"question":"What is the name of Cu₂O, assuming oxide is O²⁻?","choices":["Copper(II) oxide","Copper(I) oxide","Copper dioxide","Copper(III) oxide"],"answer":1,"explanation":"Two copper ions balance one oxide ion, so each copper is +1: copper(I) oxide.","id":"formulas-6","level":"Reinforce","section":1}],"stoichiometry":[{"question":"What must a balanced chemical equation conserve?","choices":["The number of molecules","The number of atoms of each element","The volume of every substance","The physical state"],"answer":1,"explanation":"Atoms are rearranged, not created or destroyed, in an ordinary chemical reaction.","id":"stoichiometry-1","level":"Recognize","section":0},{"question":"Why should you balance an equation by changing coefficients instead of subscripts?","choices":["Subscripts are always 1","Changing a subscript changes the chemical substance","Coefficients change the element identity","Subscripts do not affect atom counts"],"answer":1,"explanation":"A subscript defines composition. Changing H₂O to H₂O₂ creates a different substance.","callback":{"moduleId":"formulas","section":0},"id":"stoichiometry-2","level":"Explain","section":0},{"question":"In N₂ + 3H₂ → 2NH₃, how many moles NH₃ form from 6.0 mol H₂ if N₂ is excess?","choices":["2.0 mol","4.0 mol","6.0 mol","12 mol"],"answer":1,"explanation":"6.0 mol H₂ × (2 mol NH₃ / 3 mol H₂) = 4.0 mol NH₃.","id":"stoichiometry-3","level":"Apply","section":1},{"question":"For 2H₂ + O₂ → 2H₂O, 3 mol H₂ and 2 mol O₂ can form at most…","choices":["2 mol H₂O","3 mol H₂O","4 mol H₂O","5 mol H₂O"],"answer":1,"explanation":"H₂ limits the reaction: 3 mol H₂ yields 3 mol H₂O and uses 1.5 mol O₂.","id":"stoichiometry-4","level":"Reason","section":2},{"question":"For 2Mg + O₂ → 2MgO, 4.8 g Mg reacts with excess oxygen. Use Mg = 24 g/mol and MgO = 40 g/mol. What mass of MgO forms?","choices":["2.9 g","4.8 g","8.0 g","40 g"],"answer":2,"explanation":"4.8 g / 24 g mol⁻¹ = 0.20 mol Mg. The 1:1 mole ratio gives 0.20 mol MgO × 40 g/mol = 8.0 g.","callback":{"moduleId":"atoms-moles","section":2},"id":"stoichiometry-5","level":"Connect","section":1},{"question":"An experiment produces 6.0 g when the theoretical yield is 8.0 g. What is the percent yield?","choices":["25%","75%","80%","133%"],"answer":1,"explanation":"Percent yield = actual / theoretical × 100 = 6.0 / 8.0 × 100 = 75%.","id":"stoichiometry-6","level":"Reinforce","section":2}],"aqueous":[{"question":"Which particles carry electric current in an aqueous NaCl solution?","choices":["Mobile ions","Only neutral NaCl molecules","Stationary atoms","Photons"],"answer":0,"explanation":"Dissolved Na⁺ and Cl⁻ ions move through the solution and carry charge.","id":"aqueous-1","level":"Recognize","section":0},{"question":"Why do spectator ions disappear from a net ionic equation?","choices":["They cease to exist","They are identical on both sides and do not undergo the net change","They always form a gas","Their charges are zero"],"answer":1,"explanation":"Spectator ions remain dissolved and cancel because they occur unchanged on both sides.","id":"aqueous-2","level":"Explain","section":1},{"question":"Which species is oxidized when Zn(s) reacts with Cu²⁺(aq) to form Zn²⁺ and Cu(s)?","choices":["Zn","Cu²⁺","Zn²⁺","Cu"],"answer":0,"explanation":"Zn goes from oxidation state 0 to +2, an increase, so zinc is oxidized.","id":"aqueous-3","level":"Apply","section":2},{"question":"Mix AgNO₃(aq) and NaCl(aq). Which is the net ionic equation for the precipitate?","choices":["Na⁺ + NO₃⁻ → NaNO₃(s)","Ag⁺ + Cl⁻ → AgCl(s)","Ag⁺ + Na⁺ → AgNa(s)","AgNO₃ → Ag + NO₃"],"answer":1,"explanation":"AgCl is sparingly soluble. Sodium and nitrate remain spectator ions.","id":"aqueous-4","level":"Reason","section":1},{"question":"For Zn + Cu²⁺ → Zn²⁺ + Cu, how many electrons does each Zn atom lose, and why?","choices":["One, because there is one Zn atom","Two, because its charge increases from 0 to +2","Two, because Cu gains protons","None, because mass is conserved"],"answer":1,"explanation":"Losing two negative electrons produces Zn²⁺. Charge bookkeeping connects ion formation to oxidation.","callback":{"moduleId":"atoms-moles","section":0},"id":"aqueous-5","level":"Connect","section":2},{"question":"In Mg(s) + 2H⁺(aq) → Mg²⁺(aq) + H₂(g), what is reduced?","choices":["Mg","H⁺","Mg²⁺","Nothing"],"answer":1,"explanation":"H⁺ gains electrons to become H₂, changing hydrogen’s oxidation state from +1 to 0.","id":"aqueous-6","level":"Reinforce","section":2}],"thermochemistry":[{"question":"A reaction has ΔH = −125 kJ mol⁻¹. Which statement is correct?","choices":["It is endothermic","It releases heat to the surroundings","The products must be hotter","Entropy must decrease"],"answer":1,"explanation":"Negative ΔH means the system releases heat at constant pressure; the process is exothermic.","id":"thermochemistry-1","level":"Recognize","section":1},{"question":"If a reaction warms the surrounding water, the reaction system usually…","choices":["absorbs heat from that water","releases heat to that water","has no energy change","must have positive ΔH"],"answer":1,"explanation":"Heat gained by the surroundings is lost by the system, if other heat transfers are negligible.","id":"thermochemistry-2","level":"Explain","section":0},{"question":"How much heat warms 10.0 g water by 5.00 °C? Use c = 4.18 J/(g·°C).","choices":["8.36 J","20.9 J","209 J","2090 J"],"answer":2,"explanation":"q = mcΔT = 10.0 × 4.18 × 5.00 = 209 J.","id":"thermochemistry-3","level":"Apply","section":2},{"question":"Reversing a reaction changes ΔH = −50 kJ to…","choices":["−100 kJ","−50 kJ","0 kJ","+50 kJ"],"answer":3,"explanation":"Enthalpy is a state function. Reversing the direction reverses the sign of the change.","id":"thermochemistry-4","level":"Reason","section":1},{"question":"A reaction releases 100 kJ per mole of reaction as written. What is ΔH for twice that reaction?","choices":["−200 kJ","−100 kJ","+100 kJ","+200 kJ"],"answer":0,"explanation":"Doubling all stoichiometric coefficients doubles the enthalpy change. Release is negative for the system.","callback":{"moduleId":"stoichiometry","section":1},"id":"thermochemistry-5","level":"Connect","section":1},{"question":"A system absorbs 30 J heat and does 10 J work on its surroundings. Using ΔU = q + w, ΔU is…","choices":["−40 J","−20 J","+20 J","+40 J"],"answer":2,"explanation":"q = +30 J and w = −10 J, so ΔU = +20 J.","id":"thermochemistry-6","level":"Reinforce","section":0}],"electronic":[{"question":"How many orbitals are in a p subshell?","choices":["1","2","3","6"],"answer":2,"explanation":"A p subshell contains three orbitals. Each orbital can contain up to two electrons, so a p subshell can hold six electrons total.","id":"electronic-1","level":"Recognize","section":1},{"question":"An atomic orbital describes…","choices":["an exact circular electron path","a region described by an electron probability distribution","a proton orbit","a fixed electron speed"],"answer":1,"explanation":"Orbitals describe probability distributions, rather than classical fixed paths.","id":"electronic-2","level":"Explain","section":1},{"question":"What is the maximum number of electrons in a p subshell?","choices":["2","3","6","10"],"answer":2,"explanation":"Three p orbitals can each contain two electrons, for six in total.","id":"electronic-3","level":"Apply","section":1},{"question":"If a photon’s frequency doubles, its energy…","choices":["halves","stays constant","doubles","quadruples"],"answer":2,"explanation":"E = hν: photon energy is proportional to frequency.","id":"electronic-4","level":"Reason","section":0},{"question":"A neutral sodium atom has 11 electrons. Forming Na⁺ primarily removes…","choices":["a 1s electron","the outer 3s electron","a proton","a neutron"],"answer":1,"explanation":"Na has configuration [Ne]3s¹. Removing the outer electron leaves ten electrons while its eleven protons preserve sodium’s identity.","callback":{"moduleId":"atoms-moles","section":0},"id":"electronic-5","level":"Connect","section":2},{"question":"Compared with red light, higher-frequency violet light has photons with…","choices":["less energy","the same energy","more energy","zero energy"],"answer":2,"explanation":"Photon energy E = hν increases with frequency.","id":"electronic-6","level":"Reinforce","section":0}],"periodic":[{"question":"Elements in the same main-group column tend to share…","choices":["the same mass","similar valence-electron patterns","the same neutron number","identical atomic radii"],"answer":1,"explanation":"Similar valence configurations help explain recurring chemical behavior.","id":"periodic-1","level":"Recognize","section":0},{"question":"Why does atomic radius generally decrease across a period?","choices":["Nuclear attraction increases while electrons enter the same principal shell","Protons are lost","All shielding disappears","Electrons enter successively higher principal shells"],"answer":0,"explanation":"Increasing effective nuclear attraction generally pulls electrons in the same shell closer.","id":"periodic-2","level":"Explain","section":0},{"question":"Which atom is expected to have the larger first ionization energy?","choices":["Na","Mg","K","Rb"],"answer":1,"explanation":"Among these choices, Mg is farther right and in a smaller principal shell than K or Rb; its valence electron is held more strongly.","id":"periodic-3","level":"Apply","section":1},{"question":"Which neutral atom is usually larger: Li or K?","choices":["Li, because it is lighter","K, because its outer electron occupies a higher principal shell","They are identical","Cannot compare elements in one group"],"answer":1,"explanation":"Down a group, added principal shells generally increase atomic size.","id":"periodic-4","level":"Reason","section":0},{"question":"Why does Na commonly form Na⁺ while Cl commonly forms Cl⁻?","choices":["Both lose protons","Their valence configurations favor losing one versus gaining one electron","They must have equal masses","Both gain one electron"],"answer":1,"explanation":"Na is [Ne]3s¹; Cl is [Ne]3s²3p⁵. Electron transfer can produce filled valence shells while balancing opposite charges.","callback":{"moduleId":"electronic","section":2},"id":"periodic-5","level":"Connect","section":0},{"question":"Which bond is expected to have the largest electronegativity difference?","choices":["C–C","N–N","H–H","H–F"],"answer":3,"explanation":"Identical atoms have zero electronegativity difference. Fluorine attracts shared electrons much more strongly than hydrogen.","id":"periodic-6","level":"Reinforce","section":2}],"bonding":[{"question":"A covalent bond involves…","choices":["shared electron density between atoms","transfer of neutrons","destruction of electrons","shared atomic nuclei"],"answer":0,"explanation":"Covalent bonding involves shared electron density that stabilizes the bonded arrangement.","id":"bonding-1","level":"Recognize","section":0},{"question":"Which statement about resonance is correct?","choices":["The molecule rapidly switches between Lewis structures","Atoms move to new positions in each contributor","The real structure is a delocalized hybrid","Resonance only occurs in ions"],"answer":2,"explanation":"Resonance contributors are bookkeeping representations of one delocalized electronic structure.","id":"bonding-2","level":"Explain","section":2},{"question":"How many valence electrons belong in a Lewis structure of CO₂?","choices":["8","12","16","22"],"answer":2,"explanation":"Carbon contributes 4 and each oxygen 6: 4 + 2 × 6 = 16.","callback":{"moduleId":"periodic","section":0},"id":"bonding-3","level":"Apply","section":1},{"question":"Which change is allowed between valid resonance contributors?","choices":["Moving atoms to new positions","Moving electron pairs while keeping atom connectivity","Changing the total electron count","Changing the total charge"],"answer":1,"explanation":"Resonance changes electron bookkeeping, not nuclei, connectivity, total electrons, or total charge.","id":"bonding-4","level":"Reason","section":2},{"question":"An oxygen atom has three lone pairs and one single bond. Its formal charge is…","choices":["−1","0","+1","+2"],"answer":0,"explanation":"Formal charge = 6 − 6 − 1 = −1. The six valence electrons expected for oxygen come from its group.","callback":{"moduleId":"periodic","section":0},"id":"bonding-5","level":"Connect","section":1},{"question":"A nitrogen atom with four single bonds and no lone pairs has formal charge…","choices":["−1","0","+1","+4"],"answer":2,"explanation":"Formal charge = 5 − 0 − 4 = +1, as for nitrogen in NH₄⁺.","id":"bonding-6","level":"Reinforce","section":1}],"geometry":[{"question":"In VSEPR, a double bond counts as how many electron domains around a central atom?","choices":["1","2","3","4"],"answer":0,"explanation":"Each bonding region, whether single, double, or triple, counts as one electron domain.","id":"geometry-1","level":"Recognize","section":0},{"question":"Why is water bent rather than linear?","choices":["Oxygen has two bonding domains and two lone pairs","The O–H bonds are nonpolar","Hydrogen has lone pairs","All three-atom molecules are bent"],"answer":0,"explanation":"Four electron domains have approximately tetrahedral arrangement; two are lone pairs, leaving bent molecular geometry.","callback":{"moduleId":"bonding","section":1},"id":"geometry-2","level":"Explain","section":0},{"question":"Which molecule is nonpolar because its bond dipoles cancel by symmetry?","choices":["H₂O","NH₃","CO₂","SO₂"],"answer":2,"explanation":"CO₂ is linear with two equal C=O dipoles in opposite directions.","id":"geometry-3","level":"Apply","section":1},{"question":"A central atom has three bonding domains and no lone pairs. The molecular geometry is…","choices":["linear","trigonal planar","tetrahedral","trigonal pyramidal"],"answer":1,"explanation":"Three electron domains arrange approximately 120° apart in a plane.","id":"geometry-4","level":"Reason","section":0},{"question":"Which sequence best predicts molecular polarity?","choices":["Count atoms only","Find Lewis structure, infer shape, then combine bond dipoles","Use molar mass only","Assume every polar bond makes a polar molecule"],"answer":1,"explanation":"Lewis electron bookkeeping identifies lone pairs; VSEPR gives shape; the vector sum of dipoles determines molecular polarity.","callback":{"moduleId":"bonding","section":1},"id":"geometry-5","level":"Connect","section":1},{"question":"NH₃ has three N–H bonds and one lone pair on N. Its molecular geometry is…","choices":["trigonal planar","linear","trigonal pyramidal","square planar"],"answer":2,"explanation":"Four electron domains give tetrahedral electron geometry, but the positions of the three atoms define a trigonal pyramid.","id":"geometry-6","level":"Reinforce","section":0}],"gases":[{"question":"Which temperature scale belongs in PV = nRT?","choices":["Celsius","Fahrenheit","Kelvin","Any scale without conversion"],"answer":2,"explanation":"The ideal-gas law uses absolute temperature in kelvin.","id":"gases-1","level":"Recognize","section":0},{"question":"At constant amount and volume, what happens to ideal-gas pressure when Kelvin temperature doubles?","choices":["It halves","It stays constant","It doubles","It quadruples"],"answer":2,"explanation":"From PV = nRT, with n and V fixed, P is directly proportional to absolute temperature.","id":"gases-2","level":"Explain","section":0},{"question":"At fixed amount and temperature, reducing ideal-gas volume from 4.0 L to 2.0 L changes pressure from 1.0 atm to…","choices":["0.50 atm","1.0 atm","2.0 atm","4.0 atm"],"answer":2,"explanation":"Boyle’s law gives P₁V₁ = P₂V₂, so P₂ = 2.0 atm.","id":"gases-3","level":"Apply","section":0},{"question":"Why do real gases deviate most from ideal behavior at high pressure and low temperature?","choices":["Particle volume and attractions become more important","Particles become massless","Gas particles stop moving entirely","The gas constant becomes zero"],"answer":0,"explanation":"Close spacing and lower kinetic energy make finite particle volume and intermolecular attractions significant.","id":"gases-4","level":"Reason","section":2},{"question":"An ideal mixture contains 1 mol He and 3 mol Ne at total pressure 4 atm. What is the He partial pressure?","choices":["1 atm","2 atm","3 atm","4 atm"],"answer":0,"explanation":"Mole fraction He = 1/(1 + 3) = 0.25; PHe = 0.25 × 4 = 1 atm.","callback":{"moduleId":"atoms-moles","section":2},"id":"gases-5","level":"Connect","section":1},{"question":"Equal amounts of two ideal gases at the same temperature and pressure occupy…","choices":["equal volumes","volumes proportional to molar mass","zero volume","unpredictable volumes"],"answer":0,"explanation":"PV = nRT contains amount, temperature, and pressure, not gas identity.","id":"gases-6","level":"Reinforce","section":0}],"imf":[{"question":"Which attraction is present between all atoms and molecules?","choices":["Hydrogen bonding","London dispersion","Ionic bonding","Metallic bonding"],"answer":1,"explanation":"Fluctuating electron distributions produce dispersion attractions even in nonpolar particles.","id":"imf-1","level":"Recognize","section":0},{"question":"Why can water molecules hydrogen-bond to each other?","choices":["They contain any hydrogen atom","Their H atoms are bonded to O, and O has lone pairs","They contain ionic H⁺ only","All bent molecules hydrogen-bond"],"answer":1,"explanation":"Hydrogen bonding involves H attached to N, O, or F interacting with a suitable lone pair.","callback":{"moduleId":"geometry","section":1},"id":"imf-2","level":"Explain","section":1},{"question":"Which change generally accompanies stronger intermolecular forces?","choices":["Higher vapor pressure","Lower boiling point","Higher boiling point","Lower viscosity"],"answer":2,"explanation":"Stronger attractions require more energy for molecules to escape into the gas phase, so boiling point tends to rise.","id":"imf-3","level":"Apply","section":2},{"question":"At the same temperature, a liquid with stronger attractions generally has…","choices":["higher vapor pressure","lower vapor pressure","no liquid phase","a lower boiling point"],"answer":1,"explanation":"Stronger attractions make escape into the vapor less favorable, reducing vapor pressure.","id":"imf-4","level":"Reason","section":2},{"question":"CO₂ is nonpolar but condenses at sufficiently low temperature. What explains the attraction?","choices":["Nonpolar molecules cannot attract","Its electrons create London dispersion forces","It must contain permanent molecular dipoles","Its C=O bonds must be ionic"],"answer":1,"explanation":"Cancellation of permanent bond dipoles does not eliminate fluctuating electron distributions and dispersion.","callback":{"moduleId":"geometry","section":1},"id":"imf-5","level":"Connect","section":0},{"question":"Melting ice primarily disrupts…","choices":["O–H covalent bonds within every molecule","some intermolecular hydrogen-bond organization","oxygen nuclei","all electrons"],"answer":1,"explanation":"Phase changes reorganize intermolecular attractions while preserving the water molecules.","id":"imf-6","level":"Reinforce","section":2}],"solutions":[{"question":"Molarity is defined as…","choices":["moles solute per liter of solution","grams solute per liter of solvent","moles solute per kilogram of solvent","liters solute per mole"],"answer":0,"explanation":"M = nsolute / Vsolution in liters. Molality instead uses kilograms of solvent.","id":"solutions-1","level":"Recognize","section":1},{"question":"Why does dissolving NaCl ideally affect freezing point more than dissolving the same molal amount of glucose?","choices":["NaCl has larger molecules","NaCl dissociates into more dissolved particles","Glucose always precipitates","NaCl changes the solvent mass to zero"],"answer":1,"explanation":"Colligative properties depend on particle concentration. NaCl ideally produces two ions per formula unit.","callback":{"moduleId":"aqueous","section":0},"id":"solutions-2","level":"Explain","section":2},{"question":"What is the molarity of 0.20 mol solute in 0.50 L of solution?","choices":["0.10 M","0.40 M","2.5 M","4.0 M"],"answer":1,"explanation":"M = 0.20 mol / 0.50 L = 0.40 mol/L.","id":"solutions-3","level":"Apply","section":1},{"question":"Which solution ideally has the greatest freezing-point depression at the same molality?","choices":["Glucose","NaCl","CaCl₂","All are identical"],"answer":2,"explanation":"CaCl₂ ideally produces about three ions per formula unit, giving the largest particle count and largest colligative effect.","id":"solutions-4","level":"Reason","section":2},{"question":"How much 2.0 M stock is needed to prepare 100 mL of 0.50 M solution?","choices":["10 mL","25 mL","50 mL","400 mL"],"answer":1,"explanation":"Conserving solute moles gives M₁V₁ = M₂V₂, so V₁ = 25 mL. Dilute to a final volume of 100 mL.","callback":{"moduleId":"measurement","section":2},"id":"solutions-5","level":"Connect","section":1},{"question":"Diluting a solution with pure solvent, without loss of solute, changes…","choices":["solute moles and concentration equally","concentration but not solute moles","solute identity","moles of every solute to zero"],"answer":1,"explanation":"Adding solvent increases volume while preserving solute amount, so molarity decreases.","id":"solutions-6","level":"Reinforce","section":1}],"kinetics":[{"question":"Reaction rate describes…","choices":["how fast concentrations change","the final equilibrium ratio alone","whether ΔG is negative","the total mass only"],"answer":0,"explanation":"Kinetics concerns how quickly a reaction proceeds; equilibrium concerns its eventual composition.","id":"kinetics-1","level":"Recognize","section":0},{"question":"What does a catalyst change?","choices":["ΔG° of reaction","Equilibrium constant","Activation energy","Stoichiometric coefficients"],"answer":2,"explanation":"A catalyst changes the pathway and lowers activation energy without changing the initial/final thermodynamic states.","id":"kinetics-2","level":"Explain","section":2},{"question":"For rate = k[A]², doubling [A] at fixed temperature changes the rate by a factor of…","choices":["1/2","2","4","8"],"answer":2,"explanation":"The concentration is squared: (2[A])² = 4[A]².","id":"kinetics-3","level":"Apply","section":1},{"question":"Can the rate-law exponents for an overall multistep reaction always be read from its balanced equation?","choices":["Yes, for all reactions","No; the rate law generally requires experimental evidence","Only if coefficients are integers","Only for aqueous reactions"],"answer":1,"explanation":"Overall stoichiometry need not describe the mechanism or rate-determining events.","id":"kinetics-4","level":"Reason","section":1},{"question":"A reaction releases heat but proceeds slowly at room temperature. Which explanation fits?","choices":["Negative ΔH guarantees high speed","It can have a substantial activation barrier","Energy conservation has failed","A balanced equation specifies its speed"],"answer":1,"explanation":"Thermochemistry tracks energy differences between states; kinetics depends on the pathway and activation barrier.","callback":{"moduleId":"thermochemistry","section":1},"id":"kinetics-5","level":"Connect","section":0},{"question":"A catalyst is added to a reaction mixture at equilibrium. What happens?","choices":["Only the forward reaction becomes faster","The equilibrium constant increases","Both directions can become faster, with no change to K","Products must become 100%"],"answer":2,"explanation":"The catalyst speeds equilibration in both directions without changing equilibrium thermodynamics.","id":"kinetics-6","level":"Reinforce","section":2}],"equilibrium":[{"question":"At dynamic equilibrium…","choices":["both reaction rates are zero","forward and reverse rates are equal","reactant and product concentrations must be equal","all reactants are consumed"],"answer":1,"explanation":"Both directions continue at equal rates, giving constant macroscopic composition.","id":"equilibrium-1","level":"Recognize","section":0},{"question":"Which change alters the numerical value of K for a given reaction?","choices":["Adding reactant","Removing product","Changing container volume","Changing temperature"],"answer":3,"explanation":"Composition or volume changes can shift the system, but K itself changes with temperature.","id":"equilibrium-2","level":"Explain","section":2},{"question":"If Q < K, which net direction moves a reaction toward equilibrium?","choices":["Toward products","Toward reactants","Neither direction","Cannot determine without a catalyst"],"answer":0,"explanation":"The current product-to-reactant ratio is too small, so net forward reaction increases Q.","id":"equilibrium-3","level":"Apply","section":1},{"question":"For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), compression at fixed temperature favors…","choices":["reactants, with more gas moles","products, with fewer gas moles","neither side under any conditions","a larger K"],"answer":1,"explanation":"Reducing volume favors the side with fewer gas particles: two product moles versus four reactant moles.","callback":{"moduleId":"gases","section":0},"id":"equilibrium-4","level":"Reason","section":2},{"question":"Why does adding a catalyst not shift the equilibrium composition?","choices":["It stops both reactions","It changes rates in both directions without changing their thermodynamic endpoint","It changes only product mass","It makes K zero"],"answer":1,"explanation":"A catalyst changes pathways and equilibration speed, not the free-energy difference between reactants and products.","callback":{"moduleId":"kinetics","section":2},"id":"equilibrium-5","level":"Connect","section":0},{"question":"For A ⇌ B, K = 4. If [A] = 0.20 M and [B] = 0.40 M, the mixture…","choices":["has Q = 2 and proceeds toward B","has Q = 4 and is at equilibrium","has Q = 0.5 and proceeds toward A","has Q = 8 and proceeds toward A"],"answer":0,"explanation":"Q = [B]/[A] = 2 < 4, so net conversion of A to B moves toward equilibrium.","id":"equilibrium-6","level":"Reinforce","section":1}],"acidbase":[{"question":"A Brønsted–Lowry acid is a…","choices":["proton donor","proton acceptor","neutron donor","species that must contain oxygen"],"answer":0,"explanation":"The Brønsted–Lowry definition describes transfer of H⁺ from an acid to a base.","id":"acidbase-1","level":"Recognize","section":0},{"question":"Which pair can form a buffer in appreciable amounts?","choices":["HCl and NaCl","CH₃COOH and CH₃COO⁻","NaCl and KCl","Pure water and sugar"],"answer":1,"explanation":"A weak acid and its conjugate base can consume small additions of base and acid, respectively.","id":"acidbase-2","level":"Explain","section":2},{"question":"What is the pH if [H₃O⁺] = 1.0 × 10⁻³ M?","choices":["−3","3","7","11"],"answer":1,"explanation":"pH = −log₁₀[H₃O⁺] = 3.00 in the usual dilute-solution approximation.","id":"acidbase-3","level":"Apply","section":1},{"question":"If pH is one unit above pKa, which form predominates?","choices":["Protonated acid HA by 10:1","Conjugate base A⁻ by 10:1","They are equal","Cannot be determined"],"answer":1,"explanation":"pH − pKa = 1 = log([A⁻]/[HA]), so [A⁻]/[HA] = 10.","id":"acidbase-4","level":"Reason","section":2},{"question":"Adding a little strong acid to an acetate/acetic-acid buffer primarily…","choices":["uses acetate to form more acetic acid","destroys all buffer instantly","changes Ka at fixed temperature","forms more OH⁻ without reaction"],"answer":0,"explanation":"H⁺ reacts with the conjugate base, shifting the acid–base equilibrium. Ka stays constant at fixed temperature.","callback":{"moduleId":"equilibrium","section":2},"id":"acidbase-5","level":"Connect","section":2},{"question":"At pH = pKa, the buffer ratio [A⁻]/[HA] is…","choices":["0.1","1","10","100"],"answer":1,"explanation":"Henderson–Hasselbalch gives 0 = log([A⁻]/[HA]), so the ratio is 1.","id":"acidbase-6","level":"Reinforce","section":2}],"solubility":[{"question":"Ksp describes equilibrium between…","choices":["a sparingly soluble solid and its dissolved ions","two ideal gases only","an acid and light","all solutes and all solvents with one universal value"],"answer":0,"explanation":"The solubility product describes a specified solid’s dissolution equilibrium at a given temperature.","id":"solubility-1","level":"Recognize","section":0},{"question":"Why is solid AgCl omitted from Ksp = [Ag⁺][Cl⁻]?","choices":["It has no atoms","Its pure-solid activity is treated as 1","Its charge is positive","It never dissolves"],"answer":1,"explanation":"Pure solids have unit activity in the equilibrium convention; dissolved ion activities determine Ksp.","id":"solubility-2","level":"Explain","section":0},{"question":"Adding NaCl to a saturated AgCl solution generally does what to AgCl solubility?","choices":["Increases it","Decreases it","Leaves it unchanged","Makes Ksp larger"],"answer":1,"explanation":"Added Cl⁻ is a common ion, increasing Qsp and shifting the dissolution equilibrium toward solid AgCl. Ksp itself is unchanged at fixed temperature.","id":"solubility-3","level":"Apply","section":1},{"question":"For CaF₂(s) ⇌ Ca²⁺ + 2F⁻ with molar solubility s in pure water, Ksp is ideally…","choices":["s²","2s²","4s³","s³/4"],"answer":2,"explanation":"[Ca²⁺] = s and [F⁻] = 2s, so Ksp = s(2s)² = 4s³.","callback":{"moduleId":"stoichiometry","section":1},"id":"solubility-4","level":"Reason","section":0},{"question":"Why can adding acid increase the solubility of a carbonate solid?","choices":["H⁺ consumes carbonate through acid–base reactions","Acid always increases every solid’s Ksp","H⁺ adds a common carbonate ion","The solid loses its atoms"],"answer":0,"explanation":"Consuming CO₃²⁻ couples acid–base and dissolution equilibria and can pull further dissolution.","callback":{"moduleId":"acidbase","section":0},"id":"solubility-5","level":"Connect","section":1},{"question":"A mixture has Qsp > Ksp. Which change is thermodynamically favored?","choices":["More dissolution only","Precipitation until the ion product falls toward Ksp","No change under any conditions","An automatic increase of Ksp"],"answer":1,"explanation":"The ion product exceeds its equilibrium value, so forming solid reduces dissolved ion concentrations.","id":"solubility-6","level":"Reinforce","section":0}],"thermodynamics":[{"question":"At constant temperature and pressure, a spontaneous forward change has…","choices":["ΔG < 0","ΔG > 0","zero activation energy","infinite speed"],"answer":0,"explanation":"Gibbs free energy decreases for a spontaneous change at fixed temperature and pressure.","id":"thermodynamics-1","level":"Recognize","section":1},{"question":"A reaction with ΔG° < 0 necessarily has what property?","choices":["It is fast","K > 1","ΔH < 0","No activation barrier"],"answer":1,"explanation":"ΔG° = −RT lnK. If ΔG° is negative, lnK is positive and K > 1. Rate is a kinetic question.","id":"thermodynamics-2","level":"Explain","section":2},{"question":"For ΔH = +20 kJ/mol and ΔS = +100 J/(mol·K), ΔG at 300 K is…","choices":["+50 kJ/mol","+20 kJ/mol","−10 kJ/mol","−30000 kJ/mol"],"answer":2,"explanation":"Convert ΔS to 0.100 kJ/(mol·K): ΔG = 20 − 300 × 0.100 = −10 kJ/mol.","callback":{"moduleId":"measurement","section":2},"id":"thermodynamics-3","level":"Apply","section":1},{"question":"A process has ΔH > 0 and ΔS > 0. It is favored by…","choices":["lower temperature in all cases","higher temperature when TΔS exceeds ΔH","no temperature","negative absolute temperature"],"answer":1,"explanation":"ΔG = ΔH − TΔS becomes negative when the positive entropy contribution outweighs the enthalpy cost.","id":"thermodynamics-4","level":"Reason","section":1},{"question":"A mixture is at equilibrium even though ΔG° ≠ 0. Which statement is consistent?","choices":["Actual ΔG = 0 and Q = K","Actual ΔG must equal ΔG°","Q must equal 1","The reaction must stop microscopically"],"answer":0,"explanation":"ΔG = ΔG° + RT ln Q. At Q = K, the terms sum to zero; standard-state ΔG° need not be zero.","callback":{"moduleId":"equilibrium","section":1},"id":"thermodynamics-5","level":"Connect","section":2},{"question":"If ΔG° = 0 at a given temperature, K equals…","choices":["0","1","10","infinity"],"answer":1,"explanation":"ΔG° = −RT ln K gives ln K = 0, so K = 1.","id":"thermodynamics-6","level":"Reinforce","section":2}],"electrochem":[{"question":"Oxidation occurs at the…","choices":["anode","cathode","salt bridge only","voltmeter only"],"answer":0,"explanation":"The anode is defined as the electrode at which oxidation occurs, in both galvanic and electrolytic cells.","id":"electrochem-1","level":"Recognize","section":0},{"question":"In a spontaneous galvanic cell, electrons flow through the wire from…","choices":["cathode to anode","anode to cathode","salt bridge to cathode","solution to salt bridge"],"answer":1,"explanation":"Oxidation at the anode produces electrons; reduction at the cathode consumes them.","id":"electrochem-2","level":"Explain","section":0},{"question":"Using standard reduction potentials +0.34 V (Cu²⁺/Cu) and −0.76 V (Zn²⁺/Zn), E° for the spontaneous Zn/Cu cell is…","choices":["−1.10 V","−0.42 V","+0.42 V","+1.10 V"],"answer":3,"explanation":"E°cell = E°cathode − E°anode = 0.34 − (−0.76) = +1.10 V.","id":"electrochem-3","level":"Apply","section":1},{"question":"Why is a salt bridge useful?","choices":["It carries electrons through the solution","Its ions maintain electrical neutrality as the half-reactions proceed","It prevents all ion motion","It changes every cell potential to zero"],"answer":1,"explanation":"Ionic motion counteracts charge buildup; electrons travel through the external circuit.","callback":{"moduleId":"aqueous","section":0},"id":"electrochem-4","level":"Reason","section":0},{"question":"What does positive E°cell imply about ΔG° and K?","choices":["ΔG° > 0 and K < 1","ΔG° < 0 and K > 1","ΔG° = 0 and K = 1","Nothing about either"],"answer":1,"explanation":"ΔG° = −nFE°cell is negative, and ΔG° = −RT ln K then requires K > 1.","callback":{"moduleId":"thermodynamics","section":2},"id":"electrochem-5","level":"Connect","section":1},{"question":"Multiplying an entire balanced cell reaction by 2 changes E°cell how?","choices":["It doubles","It halves","It is unchanged","Its sign reverses"],"answer":2,"explanation":"Both ΔG° and transferred electron amount n double, so E° = −ΔG°/(nF) is unchanged.","id":"electrochem-6","level":"Reinforce","section":1}]};
const LEGACY_SLOTS={"measurement":[2],"atoms-moles":[0],"formulas":[2],"stoichiometry":[2],"aqueous":[2],"thermochemistry":[0],"electronic":[0],"periodic":[2],"bonding":[1],"geometry":[2],"gases":[1],"imf":[2],"solutions":[3],"kinetics":[1],"equilibrium":[1],"acidbase":[3],"solubility":[2],"thermodynamics":[1],"electrochem":[1]};
const SOURCE={repository:'dhwisdom/chematlas',channel:'ChemWaypoint site companion',snapshotAt:'2026-10-16'};
const DAY=86400000;
const EVENT_KEY='chematlas-assessment-events-v1';
const COMPLETED_KEY='chematlas-genchem-completed-v1';
function courseWithOverrides(rows=[]){
 const map=new Map(BASE_COURSE.modules.map(m=>[m.id,structuredClone(m)]));
 for(const row of rows){const m=row.payload;if(row.key==='module:'+m?.id && /^[a-z0-9-]{1,80}$/.test(m.id) && Array.isArray(m.sections)&&Array.isArray(m.outcomes)&&typeof m.title==='string'&&[1,2].includes(m.semester)&&m.check)map.set(m.id,m);}
 return [...map.values()].sort((a,b)=>a.semester-b.semester||a.number-b.number||a.id.localeCompare(b.id));
}
function questionBank(m){
 let bank=Array.isArray(m.checks)&&m.checks.length>=3?m.checks:BASE_BANKS[m.id]?BASE_BANKS[m.id].map((q,i)=>(LEGACY_SLOTS[m.id]||[]).includes(i)?{...m.check,id:q.id,level:q.level,section:q.section}:q):[m.check];
 return bank.filter(q=>q&&Array.isArray(q.choices)&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<q.choices.length).map((q,i)=>{let hash=2166136261;for(const ch of JSON.stringify([q.question,q.choices,q.answer]))hash=Math.imul(hash^ch.charCodeAt(0),16777619);return {...q,id:(q.id||m.id+'-'+i)+'-'+(hash>>>0).toString(36)};});
}
function mergeEvents(a=[],b=[]){const map=new Map();for(const e of [...(Array.isArray(a)?a:[]),...(Array.isArray(b)?b:[])])if(e&&typeof e.id==='string'&&typeof e.moduleId==='string'&&Number.isFinite(e.at)&&['start','answer','finish'].includes(e.type)&&!map.has(e.id))map.set(e.id,e);return [...map.values()].sort((a,b)=>a.at-b.at||a.id.localeCompare(b.id));}
function summarize(moduleId,list=[],legacy=[],now=Date.now()){
 const own=mergeEvents(list).filter(e=>e.moduleId===moduleId),starts=own.filter(e=>e.type==='start'),finished=starts.filter(s=>own.some(e=>e.type==='finish'&&e.run===s.id));
 const lastWrong=own.filter(e=>e.type==='answer'&&!e.correct).at(-1)?.at||0;
 const successful=finished.filter(s=>{const answers=new Map();for(const e of own)if(e.type==='answer'&&e.run===s.id&&!answers.has(e.questionId))answers.set(e.questionId,e);return s.mode==='review'&&s.eligible&&s.at>lastWrong&&s.questionIds?.length>=3&&s.questionIds.every(id=>answers.get(id)?.correct);});
 const spaced=[];for(const s of successful)if(!spaced.length||s.at-spaced.at(-1).at>=DAY)spaced.push(s);
 const complete=(Array.isArray(legacy)&&legacy.includes(moduleId))||finished.length>0,lastAt=own.filter(e=>e.type!=='start').at(-1)?.at||0,latestSuccess=spaced.at(-1)?.at||0,needsReview=complete&&lastWrong>latestSuccess,mastered=complete&&spaced.length>=2&&!needsReview,dueAt=complete?(lastAt?lastAt+DAY*(mastered?7:spaced.length?3:1):now):null;
 return {complete,mastered,reviewWins:Math.min(2,spaced.length),dueAt,due:complete&&now>=dueAt,label:mastered?'Mastery demonstrated':needsReview?'Review recommended':complete?'Building mastery':'Not yet checked',lastAt,finished:finished.length};
}
function publicModule(m,detail=false){return {id:m.id,title:m.title,semester:m.semester,number:m.number,summary:m.subtitle,prerequisite:m.prerequisite,outcomes:m.outcomes,url:'https://www.chemwaypoint.com/genchem/'+m.id,...(detail?{sections:m.sections,equations:m.equations,example:m.example,vocabulary:m.vocabulary,bridge:m.bridge,lab:m.lab}:{} )};}
function cleanQuestions(questions){return questions.map(({id,question,choices,level,callback})=>({id,question,choices,level,callback}));}
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store'}});

// Website requests use the learner’s existing Supabase session.
const SB=Deno.env.get('SUPABASE_URL');
const SERVICE=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
async function rest(path,options={}){
 const r=await fetch(SB+'/rest/v1/'+path,{...options,headers:{apikey:SERVICE,authorization:'Bearer '+SERVICE,'content-type':'application/json',...options.headers},signal:AbortSignal.timeout(12000)});
 if(!r.ok){const detail=await r.json().catch(()=>null);if(detail?.code==='P0001')throw Object.assign(new Error(detail.message),{safe:true});throw new Error('Storage request failed ('+r.status+').');}
 const text=await r.text();return text?JSON.parse(text):null;
}
async function learnerState(userId){
 const rows=await rest('learner_state?user_id=eq.'+userId+'&select=state_key,state_value,updated_at');
 const values=Object.fromEntries(rows.map(r=>[r.state_key,r.state_value]));return {events:values[EVENT_KEY]||[],legacy:values[COMPLETED_KEY]||[],updatedAt:rows.map(r=>r.updated_at).sort().at(-1)||null};
}
async function getModules(){const rows=await rest('site_published?select=key,payload,version,published_at');return courseWithOverrides(rows);}
function progressFor(modules,state){const lessons=modules.map(m=>({...publicModule(m),...summarize(m.id,state.events,state.legacy)}));return {accountConnected:true,syncedAt:state.updatedAt,completed:lessons.filter(m=>m.complete).length,mastered:lessons.filter(m=>m.mastered).length,total:lessons.length,dueForReview:lessons.filter(m=>m.due).map(m=>({id:m.id,title:m.title,label:m.label,url:m.url})),recommendedNext:lessons.find(m=>!m.complete)||null,lessons,masteryRule:'Two fully correct, eligible review sets on later days. Immediate repeats are practice.',source:SOURCE};}
async function handleBridge(req){
 if(req.method!=='POST')return json({error:'Method not allowed'},405);
 const raw=await req.text();if(raw.length>20000)return json({error:'Request too large'},413);
 const authorization=req.headers.get('authorization')||'';
 if(!authorization.startsWith('Bearer '))return json({error:'Sign in to ChemWaypoint to use your learning companion.'},401);
 const auth=await fetch(SB+'/auth/v1/user',{headers:{apikey:SERVICE,authorization},signal:AbortSignal.timeout(10000)});
 if(!auth.ok)return json({error:'Your session expired. Sign in again to continue.'},401);
 const actor=await auth.json();
 if(!actor.id||!actor.email_confirmed_at||actor.is_anonymous)return json({error:'Confirm your ChemWaypoint email before using saved practice.'},403);
 let envelope;try{envelope=JSON.parse(raw);}catch{return json({error:'Invalid request'},400);}
 const {action,args={}}=envelope;
 if(!args||typeof args!=='object'||Array.isArray(args))return json({error:'Invalid arguments'},400);
 if(action==='lookup_compound'){
  const name=String(args.name||'').trim();if(!name||name.length>150)return json({error:'Enter one compound name.'},400);
  const response=await fetch('https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/'+encodeURIComponent(name)+'/property/MolecularFormula,MolecularWeight,IUPACName,CanonicalSMILES,InChIKey/JSON',{signal:AbortSignal.timeout(15000)});
  if(!response.ok)return json({error:response.status===404?'No compound found. Try a more specific name.':'PubChem is temporarily unavailable. Please try again.'},response.status===404?404:502);
  const payload=await response.json();return json({query:name,source:'NIH PubChem',compounds:(payload.PropertyTable?.Properties||[]).slice(0,5).map(p=>({...p,url:'https://pubchem.ncbi.nlm.nih.gov/compound/'+p.CID}))});
 }
 const modules=await getModules();
 if(action==='search_lessons'){
 const query=String(args.query||'').toLowerCase().trim();const words=query.split(/\s+/).filter(Boolean);let found=modules.filter(m=>!args.semester||m.semester===args.semester).map(m=>{const title=(m.title+' '+m.id).toLowerCase();const all=JSON.stringify(m).toLowerCase();return {m,score:words.reduce((s,w)=>s+(title.includes(w)?5:all.includes(w)?1:0),0)};}).filter(x=>!query||x.score>0).sort((a,b)=>b.score-a.score);return json({lessons:found.slice(0,Math.min(20,Math.max(1,args.limit||8))).map(x=>publicModule(x.m)),source:SOURCE});
 }
 if(action==='get_lesson'){const m=modules.find(m=>m.id===args.module_id);return m?json({lesson:publicModule(m,true),source:SOURCE}):json({error:'Lesson not found. Search lessons for an exact module ID.'},404);}
 const userId=actor.id;
 if(action==='get_companion_status')return json({accountConnected:!!userId,lessonsAvailable:modules.length,accountMatching:'Uses your signed-in ChemWaypoint account.',source:SOURCE,website:'https://www.chemwaypoint.com'});

 const state=await learnerState(userId);
 if(action==='get_learning_progress')return json(progressFor(modules,state));
 if(action==='create_practice_set'){
 const m=modules.find(m=>m.id===args.module_id);if(!m)return json({error:'Lesson not found'},404);
 const current=summarize(m.id,state.events,state.legacy);const bank=questionBank(m);if(bank.length<3)return json({error:'This lesson needs at least three valid concept checks before tracked practice is available.'},422);
 const primary=bank.slice(0,5);const selected=current.complete&&bank.length>5?[bank[5],...primary.filter((_,i)=>i!==current.finished%3)]:primary;
 const id=crypto.randomUUID();const now=Date.now();const run={id,type:'start',moduleId:m.id,at:now,mode:current.complete?'review':'lesson',eligible:current.complete&&current.due,questionIds:selected.map(q=>q.id),source:'chemwaypoint-companion'};
 await rest('companion_practice_sessions',{method:'POST',body:JSON.stringify({id,user_id:userId,module_id:m.id,questions:selected,run})});
 return json({sessionId:id,moduleId:m.id,title:m.title,questions:cleanQuestions(selected),mode:run.mode,eligibleSpacedReview:run.eligible,expiresAt:new Date(now+7200000).toISOString(),instructions:'Present one question at a time. Record each first answer without coaching before submission. Submit all zero-based choice indices once; explanations are returned after grading. Never infer answers on the learner’s behalf.',masteryRule:'Completion and mastery are separate. Two later-day, fully correct reviews are required for mastery.'});
 }
 if(action==='submit_practice_set'){
 if(!/^[a-f0-9-]{36}$/.test(args.session_id||'')||!Array.isArray(args.choices)||args.choices.length>6||!args.choices.every(Number.isInteger))return json({error:'Provide the session ID and integer choice indices.'},400);
 const owned=await rest('companion_practice_sessions?id=eq.'+args.session_id+'&user_id=eq.'+userId+'&select=id');if(!owned.length)return json({error:'Practice set not found'},404);
 // Server/database computes grades; callers never supply correctness or mastery.
 const result=await rest('rpc/companion_submit_practice',{method:'POST',body:JSON.stringify({p_user_id:userId,p_session_id:args.session_id,p_choices:args.choices})});
 const next=await learnerState(userId);return json({...result,mastery:summarize(result.moduleId,next.events,next.legacy)});
 }
 return json({error:'Unknown action'},400);
}
const SITE_ORIGINS=new Set(['https://www.chemwaypoint.com','https://chemwaypoint.com']);
async function serveSiteCompanion(req){
 const origin=req.headers.get('origin');
 if(origin&&!SITE_ORIGINS.has(origin))return json({error:'Origin is not allowed.'},403);
 const headers={'Vary':'Origin','Access-Control-Allow-Methods':'POST, OPTIONS','Access-Control-Allow-Headers':'authorization, apikey, content-type','Access-Control-Max-Age':'600'};
 if(origin)headers['Access-Control-Allow-Origin']=origin;
 let response;
 if(req.method==='OPTIONS')response=new Response(null,{status:204});
 else try{response=await handleBridge(req);}catch(e){response=json({error:e.safe?e.message:'Could not connect to your learning tools. Please try again.'},e.safe?422:502);}
 for(const [key,value]of Object.entries(headers))response.headers.set(key,value);
 return response;
}
Deno.serve(serveSiteCompanion);
